"use strict";

/*
 * C3 Migration Studio.
 * Every research figure on the Evidence tab is read from data/dashboard_data.json
 * (generated by scripts/summarize_evidence.py --dashboard-json). This file holds
 * no research numbers: the only numeric literals are UI values in LAYOUT below,
 * plus zero and one in ordinary logic. tests/test_dashboard_data.py checks this.
 */

/* ===== LAYOUT (UI values only; no research results) ===== */
const LAYOUT = {
  percentScale: 100,
  bytesPerKb: 1024,
  shortHash: 7,
  msPerSecond: 1000,
  secondsPerMinute: 60,
};
/* ===== END LAYOUT ===== */

// Replace a container's content; nested arrays are flattened and empty entries dropped.
function fill(root, ...children) {
  root.replaceChildren(...children.flat(Infinity).filter((c) => c !== null && c !== undefined && c !== false));
}

function h(tag, attrs, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs || {})) {
    if (value === null || value === undefined || value === false) continue;
    if (key === "class") node.className = value;
    else if (key === "text") node.textContent = value;
    else if (key.startsWith("on")) node.addEventListener(key.slice("on".length), value);
    else node.setAttribute(key, value === true ? "" : value);
  }
  for (const child of children.flat(Infinity)) {
    if (child === null || child === undefined || child === false) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

/* ===== EVIDENCE ===== */
const Evidence = (() => {
  let DATA = null;
  const state = { app: null, section: "functions", sqlFilter: "all", sqlSearch: "", sqlView: "sites",
    matrix: { status: "all", op: "all", stage: "all" } };
  const NOT_MEASURED = "Not yet measured";
  const NOT_APPLICABLE = "Not applicable";
  const SECTIONS = ["functions", "overview", "sql", "models", "impact", "evaluation", "reports"];
  const APP_SCOPED = new Set(["overview", "sql", "models", "impact"]);
  const NUMERIC_CELL = /^-?\d[\d.,]*%?(\s*\(\d+\/\d+\))?$/;
  const EXPERIMENT_LABELS = { e1: "E1 behavioural equivalence", e2: "E2 schema fidelity", e3: "E3 Alembic round trip",
    e4: "E4 injection negatives", tests: "Regression tests" };
  const STATUS_CLASS = { "Implemented and measured": "good", Partial: "partial", "Not implemented": "not-implemented" };

  // ---------- data access ----------
  const measurements = (pred) => DATA.measurements.filter(pred);
  const measurement = (app, metric, stage) =>
    DATA.measurements.find((m) => m.app === app && m.metric === metric && (!stage || m.stage === stage)) || null;
  const byId = (id) => DATA.measurements.find((m) => m.id === id) || null;
  const appLabel = (id) => (id === "all" ? "All applications" : (DATA.apps[id] ? DATA.apps[id].label : id));

  function formatValue(m) {
    if (!m || m.status === "not_measured") return NOT_MEASURED;
    if (m.value === null || m.value === undefined) return NOT_APPLICABLE;
    if (m.unit === "seconds") return `${m.value} s`;
    return m.unit === "percent" ? `${m.value}%` : String(m.value);
  }
  function ratio(m) {
    return m && m.numerator !== null && m.numerator !== undefined && m.denominator !== null && m.denominator !== undefined
      ? `${m.numerator}/${m.denominator}` : "";
  }
  function statusBadge(status) {
    const text = { measured: "measured", derived: "derived", not_measured: "not measured" }[status] || status;
    return h("span", { class: `badge ${status}`, text });
  }
  function stageBadge(m) {
    return h("span", { class: `badge stage-badge ${m.stage}`, text: m.stage_label, title: DATA.stage_definitions[m.stage] || "" });
  }

  // ---------- drawer ----------
  const drawer = () => document.getElementById("detail-drawer");
  function openDrawer(title, ...content) {
    document.getElementById("detail-title").textContent = title;
    fill(document.getElementById("detail-body"), content);
    drawer().hidden = false;
    document.getElementById("scrim").hidden = false;
    document.getElementById("detail-close").focus();
  }
  function closeDrawer() {
    drawer().hidden = true;
    document.getElementById("scrim").hidden = true;
  }

  function definitionList(pairs) {
    return h("dl", {}, pairs.filter(([, v]) => v !== null && v !== undefined && v !== "").map(([k, v]) => [
      h("dt", { text: k }), h("dd", {}, v),
    ]));
  }

  function relatedSites(m) {
    const review = m.metric === "manual_review_rate" && DATA.manual_review ? DATA.manual_review.apps[m.app] : null;
    if (review) {
      return h("div", {},
        h("h4", { text: "Live sites not converted automatically (counted)" }),
        review.sites.length ? table(["Query ID", "Ground-truth ID", "PHP site", "Stage", "Reason code"],
          review.sites.map((s) => [s.query_id, s.gt_id || "-", h("code", { text: s.site }), s.stage, s.reason_code || "-"]))
          : h("p", { class: "muted", text: "None." }),
        h("h4", { text: "Ambiguous ground-truth sites (included in both counts)" }),
        review.ambiguous.length ? table(["Ground-truth ID", "PHP site", "Converted"],
          review.ambiguous.map((a) => [a.gt_id, h("code", { text: a.site }), a.converted ? "yes" : "no"]))
          : h("p", { class: "muted", text: "None." }),
        h("h4", { text: "Non-live sites (excluded)" }),
        review.excluded_non_live.length ? table(["Query ID", "PHP site", "Ground-truth label"],
          review.excluded_non_live.map((e) => [e.query_id, h("code", { text: e.site }), e.gt_label || "-"]))
          : h("p", { class: "muted", text: "None." }),
        h("p", { class: "muted", text: `${DATA.manual_review.formula} ${DATA.manual_review.limits}` }));
    }
    const stageSites = DATA.stage_sites[`${m.app}|${m.stage_label}`];
    if (stageSites) {
      const wanted = { recovery_precision: ["FP"], recovery_recall: ["FN"], correct_abstention: ["TN"] }[m.metric];
      const rows = stageSites.filter((s) => !wanted || wanted.includes(s.outcome));
      if (!rows.length) return h("p", { class: "muted", text: "No related sites for this metric at this stage." });
      return h("div", {}, h("h4", { text: "Related sites (from the evaluation file)" }), table(
        ["Ground-truth ID", "Query ID", "PHP site", "Outcome", "C3 status", "Reason code"],
        rows.map((s) => [s.gt_id, s.query_id || "-", h("code", { text: s.site }), s.outcome, s.c3_status || "-", s.reason_code || "-"]),
      ));
    }
    if (m.stage === "current-code" && DATA.records[m.app]) {
      const rows = DATA.records[m.app].filter((r) => r.unresolved_stage);
      if (!rows.length) return h("p", { class: "muted", text: "No unresolved sites for this application in the current-code run." });
      return h("div", {}, h("h4", { text: "Unresolved sites (current-code run)" }), table(
        ["Query ID", "Ground-truth ID", "PHP site", "Stage", "Reason"],
        rows.map((r) => [r.query_id, r.gt_id || "-", h("code", { text: `${r.file}:${r.line}` }), r.unresolved_stage,
          r.unresolved_reason ? `${r.unresolved_reason_code}: ${r.unresolved_reason}` : r.unresolved_reason_code]),
      ));
    }
    return null;
  }

  function showMeasurement(m) {
    const source = m.source || {};
    const fields = source.fields ? Object.entries(source.fields).map(([k, v]) => `${k}: ${v}`).join("; ") : null;
    openDrawer(m.label,
      definitionList([
        ["Application", appLabel(m.app)],
        ["Evaluation stage", stageBadge(m)],
        ["Stage meaning", DATA.stage_definitions[m.stage] || null],
        ["Value", formatValue(m)],
        ["Numerator / denominator", ratio(m) || "-"],
        ["Status", statusBadge(m.status)],
        ["Evidence file", source.file ? h("code", { text: source.file }) : "-"],
        ["Fields", fields],
        ["Derivation", source.derivation || null],
        ["Note", m.note || null],
      ]),
      relatedSites(m));
  }

  // ---------- small builders ----------
  const isNumeric = (c) => typeof c === "number" || (typeof c === "string" && NUMERIC_CELL.test(c.trim()));
  function table(headers, rows, onRow) {
    const numericColumn = headers.map((_, i) => rows.some((r) => isNumeric(r[i])) && rows.every((r) => isNumeric(r[i]) || r[i] === "-"));
    return h("div", { class: "table-wrap" }, h("table", {},
      h("thead", {}, h("tr", {}, headers.map((x, i) => h("th", { class: numericColumn[i] ? "num" : null, scope: "col", text: x })))),
      h("tbody", {}, rows.map((cells, i) => h("tr", onRow ? { tabindex: "0", onclick: () => onRow(i),
        onkeydown: (e) => { if (e.key === "Enter") onRow(i); } } : {},
        cells.map((c, j) => h("td", { class: numericColumn[j] || isNumeric(c) ? "num" : null }, c ?? "-"))))),
    ));
  }

  function kpi(m, label, foot) {
    return h("button", { type: "button", class: "kpi", onclick: () => m && showMeasurement(m), "aria-label": `${label}: ${formatValue(m)}` },
      h("div", { class: "kpi-label", text: label }),
      h("div", { class: "kpi-value", text: formatValue(m) }),
      h("div", { class: "kpi-foot" }, m ? [h("span", { text: m.stage_label }), statusBadge(m.status)] : NOT_MEASURED,
        foot ? h("span", { text: foot }) : null));
  }

  function card(title, sub, ...children) {
    return h("div", { class: "card" }, h("h3", { text: title }), sub ? h("p", { class: "sub", text: sub }) : null, children);
  }

  // ---------- charts: compact rows grouped by app; identical consecutive results share one row ----------
  const sameResult = (a, b) => formatValue(a) === formatValue(b) && ratio(a) === ratio(b) && a.status === b.status;

  function metricChart(items, options = {}) {
    const label = options.label || ((m) => m.stage_label);
    const groups = new Map();
    for (const m of items) {
      const key = options.groupBy ? options.groupBy(m) : m.app;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(m);
    }
    return h("div", { class: "metric-chart", role: "list", "aria-label": options.title || "chart" },
      [...groups].map(([group, members]) => {
        const rows = [];
        for (const m of members) {
          const last = rows[rows.length - 1];
          if (last && sameResult(last[0], m)) last.push(m);
          else rows.push([m]);
        }
        return h("div", { class: "mc-group", role: "listitem" },
          h("div", { class: "mc-app", text: appLabel(group) }),
          rows.map((row) => {
            const m = row[0];
            const fraction = m.unit === "percent" ? (m.value ?? 0) / LAYOUT.percentScale
              : (m.denominator ? m.numerator / m.denominator : 0);
            const width = Math.max(0, Math.min(LAYOUT.percentScale, fraction * LAYOUT.percentScale));
            return h("div", { class: "mc-row" },
              h("div", { class: "mc-stages" }, row.map((x) => h("button", {
                type: "button", class: `badge stage-badge ${x.stage}`, text: label(x),
                title: `${DATA.stage_definitions[x.stage] || ""} Select for the evidence.`,
                "aria-label": `${appLabel(x.app)}, ${label(x)}: ${formatValue(x)} ${ratio(x)}. Open evidence.`,
                onclick: () => showMeasurement(x),
              }))),
              h("div", { class: "mc-bar", "aria-hidden": "true" }, h("span", { class: `mc-fill ${options.tone || ""}`, style: `width:${width}%` })),
              h("div", { class: "mc-value" }, h("strong", { text: formatValue(m) }),
                ratio(m) ? h("span", { class: "muted", text: ` (${ratio(m)})` }) : null,
                m.status !== "measured" ? [" ", statusBadge(m.status)] : null));
          }));
      }));
  }

  function stageLegend() {
    return h("div", { class: "chip-row" }, Object.entries(DATA.stage_definitions).map(([key, text]) =>
      h("span", { class: `badge stage-badge ${key}`, title: text, text: key })));
  }

  function e1Chart() {
    const verdicts = ["PASS", "FAIL", "INCONCLUSIVE"];
    return h("div", { class: "metric-chart" }, DATA.experiments.e1.runs.map((run) => {
      const final = run.kind === "final";
      const open = (verdict) => {
        const m = final ? measurement(run.app, `e1_${verdict.toLowerCase()}`) : null;
        if (m) return showMeasurement(m);
        return openDrawer(`E1 ${verdict} (superseded run)`, definitionList([
          ["Application", appLabel(run.app)], ["Verdict", verdict], ["Sites", `${run.verdicts[verdict]}/${run.sites}`],
          ["Evidence file", h("code", { text: run.file })], ["Note", run.note]]));
      };
      return h("div", { class: "mc-group" },
        h("div", { class: "mc-app", text: `${appLabel(run.app)} · ${final ? "final run" : "superseded first run"}` }),
        h("div", { class: `stacked${final ? "" : " superseded"}`, "aria-hidden": "true" }, verdicts.map((v) =>
          h("span", { class: v.toLowerCase(), style: `width:${run.sites ? (run.verdicts[v] / run.sites) * LAYOUT.percentScale : 0}%` }))),
        h("div", { class: "chip-row" }, verdicts.map((v) => h("button", {
          type: "button", class: `badge ${v.toLowerCase()}`, text: `${v} ${run.verdicts[v]} of ${run.sites}`,
          "aria-label": `${appLabel(run.app)} ${final ? "final run" : "superseded run"}: ${v} ${run.verdicts[v]} of ${run.sites}. Open evidence.`,
          onclick: () => open(v),
        }))),
        final ? null : h("p", { class: "muted", text: run.note }));
    }));
  }

  // ---------- sections ----------
  function joinCounts(limitation) {
    const counts = new Map();
    for (const site of limitation.sites) counts.set(site.join_kind, (counts.get(site.join_kind) || 0) + 1);
    return [...counts].map(([kind, n]) => `${n} ${kind}`).join(", ");
  }

  function showSites(limitation) {
    openDrawer(`${limitation.fr}: ${limitation.title}`, h("p", { text: limitation.text }),
      table(["Join form", "Application", "Query ID", "Ground-truth ID", "PHP site", "Ground-truth label"],
        limitation.sites.map((s) => [s.join_kind, appLabel(s.app), s.query_id, s.gt_id || "-", h("code", { text: s.site }), s.gt_label || "-"])));
  }

  function frCard(item) {
    const refs = item.measurements.map(byId).filter(Boolean);
    const c = pp1().functions[item.fr] || {};
    const headline = (c.headline || []).map((id) => refs.find((m) => m.id === id)).filter(Boolean);
    const caption = headline.length && headline.every((m) => m.label === headline[0].label) ? headline[0].label : null;
    const siteList = item.site_list ? DATA.limitations.find((l) => l.fr === item.site_list) : null;
    const experiments = item.experiments.map((k) => h("a", { href: "#/evidence/evaluation", text: EXPERIMENT_LABELS[k] || k }));
    const apps = [...new Set(refs.map((m) => m.app))];
    const labels = [...new Set(refs.map((m) => m.label))];
    const cell = (app, label) => refs.filter((m) => m.app === app && m.label === label).map((m, i, all) => h("button", {
      type: "button", class: "linklike fr-cell", title: `${m.stage_label} · ${m.source.file || ""}`, onclick: () => showMeasurement(m),
      "aria-label": `${appLabel(m.app)}, ${m.label}, ${m.stage_label}: ${formatValue(m)} ${ratio(m)}. Open evidence.`,
      text: `${formatValue(m)}${ratio(m) ? ` (${ratio(m)})` : ""}${all.length > 1 ? ` · ${m.stage_label}` : ""}` }));
    return h("article", { class: "card fr-card", "aria-labelledby": `fr-${item.fr}` },
      h("div", { class: "fr-head" },
        h("h3", { id: `fr-${item.fr}` }, h("span", { class: "fr-id", text: item.fr }), item.title),
        h("span", { class: `badge ${STATUS_CLASS[item.status] || ""}`, text: item.status })),
      h("p", { class: "fr-req-short", title: item.requirement, text: item.requirement }),
      caption ? h("p", { class: "fr-kpi-caption", text: caption }) : null,
      headline.length ? h("div", { class: "fr-headline", "aria-label": `Headline measurements for ${item.fr}` }, headline.map((m) =>
        h("button", { type: "button", class: "fr-kpi", onclick: () => showMeasurement(m),
          "aria-label": `${appLabel(m.app)}, ${m.label}, ${m.stage_label}: ${formatValue(m)} ${ratio(m)}. Open evidence.` },
        h("span", { class: "fr-kpi-value" }, h("strong", { text: formatValue(m) }), ratio(m) ? h("span", { class: "muted", text: ` (${ratio(m)})` }) : null),
        h("span", { class: "fr-kpi-label", text: caption ? appLabel(m.app) : `${appLabel(m.app)} · ${m.label}` })))) : null,
      item.status === "Partial" && c.partial_short ? h("p", { class: "fr-main-limit" }, h("strong", { text: "Why Partial: " }), c.partial_short) : null,
      details("Evidence and limitations",
        h("blockquote", { class: "fr-req", text: item.requirement }),
        h("p", { class: "fr-limit" }, h("strong", { text: "Limitation: " }), item.limitation),
        c.main_limit ? h("p", { class: "fr-limit" }, h("strong", { text: "Main limit: " }), c.main_limit) : null,
        c.partial_reason ? h("p", { class: "fr-limit" }, h("strong", { text: "Why the status is Partial: " }), c.partial_reason) : null,
        table(["Application", ...labels], apps.map((a) => [appLabel(a), ...labels.map((l) => { const x = cell(a, l); return x.length ? x : "-"; })])),
        h("p", { class: "muted", text: "Select a value for its evidence (stage, numerator and denominator, source file)." }),
        siteList ? h("p", {}, h("button", { type: "button", class: "button", onclick: () => showSites(siteList),
          text: `Unsupported join sites: ${joinCounts(siteList)} (show sites)` })) : null,
        experiments.length ? h("p", { class: "fr-limit muted" }, "Experiments: ",
          experiments.flatMap((a, i) => (i ? [", ", a] : [a]))) : null),
      frDetails(item));
  }

  // ---------- PP1 views (DATA.pp1, built by dashboard/pp1_content.py; text from docs/c3_pp1_dashboard_content.json) ----------
  const pp1 = () => DATA.pp1;
  const appName = (id) => (id === "ams_native" ? "ams-native" : appLabel(id));
  const shown = (x) => (x === null || x === undefined ? "-" : (x.value === null || x.value === undefined ? "n/a" : String(x.value)));
  // A computed number with its source: always a button that opens the source.
  function sourced(x, label) {
    if (!x) return "-";
    return h("button", { type: "button", class: "linklike", title: x.source, text: shown(x),
      onclick: () => openDrawer(label || "Computed value", definitionList([["Value", shown(x)], ["Evidence", h("code", { text: x.source })],
        ["Derivation", x.derivation || null]])) });
  }
  function details(summary, ...children) {
    return h("details", { class: "pp1-details" }, h("summary", { text: summary }), children);
  }
  const bullets = (items) => h("ul", { class: "pp1-list" }, items.map((t) => h("li", {}, t)));
  function statusChip(key) {
    const s = pp1().statuses[key];
    return h("span", { class: `badge ${s ? s.tone : ""}`, text: s ? s.label : key });
  }
  const idsText = (list) => (list && list.length ? list.join(", ") : "-");
  function measurementButton(id, prefix) {
    const m = byId(id);
    if (!m) return null;
    return h("button", { type: "button", class: "fr-item", onclick: () => showMeasurement(m),
      "aria-label": `${appLabel(m.app)}, ${m.label}: ${formatValue(m)} ${ratio(m)}. Open evidence.` },
      h("span", { class: "what" }, h("span", { text: `${prefix || appLabel(m.app)} · ${m.label}` }), stageBadge(m)),
      h("span", { class: "val" }, h("strong", { text: formatValue(m) }), ratio(m) ? h("span", { class: "muted", text: ` (${ratio(m)})` }) : null));
  }
  function latestTestIds() {
    return DATA.experiments.tests.runs.filter((r) => r.latest).flatMap((r) =>
      ["passed", "failed", "skipped"].map((k) => `all|${r.stage_label}|${r.metric_prefix}_${k}`));
  }

  function showSourceEvidence(item, c) {
    openDrawer(`${item.fr}: source evidence`,
      h("p", { class: "muted", text: "Repository files: open them in the repository (the dashboard does not serve source files). Function names are checked to exist when the data is generated." }),
      h("h4", { text: "Implementation" }), bullets(c.code.map((r) => [h("code", { text: r.file }), " — ", r.functions.map((f, i) => [i ? ", " : "", h("code", { text: f })])])),
      h("h4", { text: "Tests" }), bullets(c.tests.map((t) => h("code", { text: t }))),
      h("h4", { text: "Commits" }), bullets(c.improvements.map((i) => [h("code", { text: i.commit }), " ", i.text])),
      h("h4", { text: "Referenced measurements" }), h("ul", { class: "fr-list" }, item.measurements.map((id) => h("li", {}, measurementButton(id)))),
      h("p", { class: "muted", text: `Status and limitation: ${DATA.functions.source}. Explanatory text: ${pp1().content_source}.` }));
  }

  function frDetails(item) {
    const c = pp1().functions[item.fr];
    if (!c) return null;
    return details("More detail: implementation, files, demonstration, improvements, tests, future work",
      details("Implementation and techniques", h("p", {}, h("strong", { text: "Research purpose: " }), c.purpose),
        h("p", { text: c.implementation }), bullets(c.techniques)),
      details("Key files and functions", bullets(c.code.map((r) => [h("code", { text: r.file }), ": ",
        r.functions.map((f, i) => [i ? ", " : "", h("code", { text: f })])]))),
      details("Demonstrable functionality", bullets(c.demonstration.map((d) => [h("strong", { text: appName(d.app) }),
        d.query_ids.length ? ` (${d.query_ids.join(", ")})` : "", ": ", d.text]))),
      details("Improvements completed", bullets(c.improvements.map((i) => [h("code", { text: i.commit }), " ", i.text]))),
      details("Tests and their results",
        bullets(c.tests.map((t) => h("code", { text: t }))),
        h("p", { class: "muted", text: "Results are the saved suite totals (all tests, including the files above):" }),
        h("ul", { class: "fr-list" }, latestTestIds().map((id) => h("li", {}, measurementButton(id, "Saved log"))))),
      details("Future work", bullets(c.future)),
      h("p", {}, h("button", { type: "button", class: "button", onclick: () => showSourceEvidence(item, c), text: "View source evidence" })));
  }

  function renderFunctions(root) {
    const fn = DATA.functions;
    const counts = {};
    for (const item of fn.items) counts[item.status] = (counts[item.status] || 0) + 1;
    const summary = fn.statuses.filter((s) => counts[s]).map((s) => `${counts[s]} ${s.toLowerCase()}`).join(", ");
    fill(root,
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: "Functions: proposal requirements FR1 to FR10" }),
        h("p", { text: "What was proposed, what was implemented, how it was tested and what remains. Open a card's sections for detail." }))),
      details("Evidence methodology", bullets(pp1().methodology),
        h("p", { class: "muted", text: `Requirement text: ${fn.requirements_source}. Statuses and limitations: ${fn.source}. Explanations: ${pp1().content_source}.` })),
      h("p", { class: "fr-summary", id: "fr-summary" }, h("strong", { text: summary }),
        h("span", { class: "muted", text: `counted from ${fn.source}` })),
      h("div", { class: "grid cards" }, fn.items.map(frCard)));
  }

  function repoLink(r) {
    return r.repository ? h("a", { href: `https://${r.repository}`, rel: "noopener", target: "_blank", text: r.repository }) : "Not recorded";
  }
  function feeLicenceNotice() {
    const f = pp1().fee_rainbow_licence;
    return h("div", { class: "notice" }, h("strong", { text: f.message }), h("p", { text: f.history }),
      h("p", {}, h("strong", { text: "Resolution: " }), f.resolution), h("p", { class: "muted", text: f.policy }));
  }
  function showRegisterRow(r) {
    const value = (k) => { const m = byId(r.measurements[k]); return m ? measurementButton(m.id, m.label) : "-"; };
    openDrawer(r.label, definitionList([
      ["Type", r.type], ["Role", r.role], ["Evaluation purpose", r.purpose], ["Origin (manifest)", r.origin || "-"],
      ["Repository (manifest)", repoLink(r)], ["Commit (manifest)", r.commit ? h("code", { text: `${r.commit} (${r.commit_date})` }) : "Not recorded"],
      ["Licence (manifest)", r.licence_manifest || "Not recorded"], ["Licence / provenance (dashboard generator)", r.licence_generator],
      ["Licence status", r.licence_status || null],
      ["Licence evidence", r.licence_evidence ? [h("code", { text: r.licence_evidence.file }), ` (${r.licence_evidence.conclusion}, ${r.licence_evidence.date})`] : null],
      ["Provenance records", bullets(r.provenance_files.map((f) => h("code", { text: f })))],
      ["Ground truth", r.ground_truth], ["Ground-truth entries", r.ground_truth_entries ? sourced(r.ground_truth_entries) : null],
      ["SQL detected", value("sql_detected")], ["SQL recovered", value("sql_recovered")], ["Converted functions", value("converted_functions")],
      ["Unresolved sites", value("unresolved_total")], ["Evidence applied", r.evidence_applied.join(", ")],
      ["Known limitations", r.limitations], ["Source display", r.display]]),
      r.licence_evidence ? feeLicenceNotice() : null);
  }
  function registerCard() {
    const reg = pp1().register;
    const cell = (r, k) => formatValue(byId(r.measurements[k]));
    return card("Applications & Licensing Register (nine evaluated applications)", "Licence and provenance as recorded; select a row for detail.",
      table(["Application", "Type", "Repository", "Licence", "Ground truth", "Detected", "Recovered", "Converted", "Unresolved", "Source display"],
        reg.map((r) => [r.label, r.type, repoLink(r),
          r.licence_status ? h("span", { class: "badge warn", text: "Inconsistent - verification required" })
            : r.licence_evidence ? [h("span", { class: "badge good", text: `${r.licence_evidence.conclusion} (verified)` }), " ", h("code", { text: r.licence_evidence.file })]
              : (r.licence_manifest || r.licence_generator),
          r.ground_truth, cell(r, "sql_detected"), cell(r, "sql_recovered"), cell(r, "converted_functions"), cell(r, "unresolved_total"), r.display]),
        (i) => showRegisterRow(reg[i])),
      reg.some((r) => r.licence_status || r.licence_evidence) ? feeLicenceNotice() : null);
  }
  function amsCard() {
    const a = pp1().ams_native;
    const keys = [["total_queries", "Detected"], ["recovered_queries", "Recovered"], ["converted_queries", "Converted"], ["unresolved_total", "Unresolved"]];
    return card("ams-native (unseen application, shown separately)", `${a.type}. ${a.purpose} ${a.limitations}`,
      table(["Run", ...keys.map(([, t]) => t)], a.runs.map((run) => [run.label, ...keys.map(([k]) => (run[k] ? sourced(run[k], `${run.label}: ${k}`) : "-"))])),
      h("h4", { text: "Licence history (both records kept)" }),
      bullets(a.licence_history.map((x) => [h("strong", { text: `${x.when}: ` }), x.text, " ", h("code", { text: x.source })])),
      h("p", { class: "muted", text: `Ground truth: ${a.ground_truth}. Evidence: ${a.evidence_applied.join(", ")}. ${a.display}.` }));
  }

  function definitionsCard() {
    return card("How to read these numbers", "Each definition names its denominators; select a value for its evidence.",
      pp1().measurement_definitions.map((d) => details(d.title, h("p", { text: d.text }),
        d.refs.length ? h("ul", { class: "fr-list" }, d.refs.map((id) => h("li", {}, measurementButton(id)))) : null,
        d.title.startsWith("E4") ? securityScope() : null)));
  }

  // Evaluation: what was and was not verified (replaces the per-application "not yet measured" table).
  function verificationScope(notMeasured) {
    const finalRun = DATA.experiments.e1.runs.find((r) => r.kind === "final");
    const suite = DATA.experiments.e1.separate_suites[0];
    const all = suite ? measurement(suite.app, "mysql_equivalence_tests_passed") : null;
    const join = suite ? measurement(suite.app, "join_rule_mysql_tests_passed") : null;
    const noE1 = notMeasured.filter((m) => m.metric === "e1_equivalence").map((m) => appLabel(m.app));
    const effort = notMeasured.filter((m) => m.metric === "migration_effort");
    const open = (m) => h("button", { type: "button", class: "linklike", onclick: () => showMeasurement(m), text: formatValue(m) });
    return card("Verification scope", "Missing evidence is shown as not measured, never as zero.", bullets([
      [`E1 behavioural equivalence on MySQL was run for ${appLabel(finalRun.app)} only`, noE1.length ? `; not run for ${noE1.join(", ")}.` : "."],
      all && join ? [`${appLabel(suite.app)} has a separate MySQL verification, not E1: `, open(all), " tests = ",
        `${all.value - join.value}`, " tests of the application's PHP against the generated functions + ", open(join),
        " direct-SQL join-rule tests."] : null,
      `Execution time is measured on one machine (${DATA.experiments.performance.machine.cpu}); it is not a benchmark of other hardware.`,
      ["Developer effort and maintainability are not claimed", effort.length ? ` (${effort[0].label}: ${NOT_MEASURED}).` : "."],
    ].filter(Boolean)));
  }

  function renderOverview(root) {
    const app = DATA.apps[state.app];
    const cur = (metric) => measurement(state.app, metric, "current-code");
    const notes = [];
    if (state.app === "clinic_inventory_legacy_hard") notes.push(DATA.disclosures.clinic.text);
    if (state.app === "fee_rainbow") notes.push(DATA.disclosures.fee_rainbow.text);
    if (state.app === "dignity_dev_hms") notes.push(DATA.disclosures.dignity_dev.text);
    if (app.note) notes.push(app.note);
    const roleClass = state.app === "dignity_dev_hms" ? "badge stage-badge fresh-holdout" : "badge";

    fill(root,
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: `Overview · ${app.label}` }),
        h("p", {}, h("span", { class: roleClass, text: app.role }), " ", app.provenance))),
      notes.map((t) => h("div", { class: "notice", text: t })),
      h("div", { class: "grid kpis" },
        kpi(cur("sql_detected"), "SQL detected"),
        kpi(cur("sql_recovered"), "SQL recovered"),
        kpi(cur("converted_functions"), "Converted functions"),
        kpi(cur("unresolved_total"), "Unresolved sites")),
      h("div", { class: "grid kpis" },
        kpi(cur("converted_general"), "Converted by general rules"),
        kpi(cur("converted_template"), "Converted by query-specific templates"),
        kpi(cur("unresolved_recovery"), "Unresolved at recovery"),
        kpi(cur("unresolved_conversion"), "Unresolved at conversion"),
        kpi(cur("manual_review_rate"), "Manual-review rate", "not developer effort")),
      h("p", { class: "muted", text: "Counts are from a fresh run of the current pipeline (stage: current code). "
        + "Recovery accuracy and conversion coverage against ground truth are on the Evaluation tab." }),
      card("All applications (current code)", "Select a row to switch application.", table(
        ["Application", "Role", "Detected", "Recovered", "Converted", "of which templates", "Unresolved"],
        Object.values(DATA.apps).map((a) => [a.label, a.role,
          formatValue(measurement(a.id, "sql_detected", "current-code")),
          formatValue(measurement(a.id, "sql_recovered", "current-code")),
          formatValue(measurement(a.id, "converted_functions", "current-code")),
          formatValue(measurement(a.id, "converted_template", "current-code")),
          formatValue(measurement(a.id, "unresolved_total", "current-code"))]),
        (i) => selectApp(Object.keys(DATA.apps)[i]))),
      registerCard(),
      amsCard(),
    );
  }

  const SQL_VIEWS = [["sites", "Per-site results (selected application)"], ["matrix", "SQL Support Matrix"],
    ["explorer", "Failure & Limitation Explorer"]];
  function sqlViewSwitch() {
    return h("div", { class: "chip-row view-switch", role: "tablist", "aria-label": "SQL Results view" }, SQL_VIEWS.map(([key, text]) =>
      h("button", { type: "button", class: `button${state.sqlView === key ? " primary" : ""}`, role: "tab",
        "aria-selected": String(state.sqlView === key), text, onclick: () => { state.sqlView = key; render(); } })));
  }

  function starWarningCard() {
    const s = pp1().star_join_sites;
    return h("div", { class: "card warn-card" },
      h("h3", { text: "Result-shape warning: converted INNER JOIN sites with a star projection" }),
      h("div", { class: "notice", text: s.warning }),
      h("p", { class: "sub", text: "These sites are converted and stay converted; the INNER JOIN rule does not check result shape. The finding per site "
        + "uses the parsed schema of the same run. Source SQL stays private (counts only)." }),
      table(["Application", "Query ID", "Projection", "Joined tables", "Tables missing from parsed schema", "Expanded output columns",
        "Duplicate projected names", "Finding"],
      s.sites.map((x) => [appName(x.app), x.query_id, x.projection.join(", "), sourced(x.join_tables), sourced(x.tables_missing_from_parsed_schema),
        sourced(x.expanded_output_columns), sourced(x.duplicate_output_names), x.finding])),
      h("p", { class: "muted" }, "Evidence: ", h("code", { text: s.source })));
  }

  function showMatrixRow(row) {
    openDrawer(row.feature, definitionList([
      ["Category", row.category], ["Status", statusChip(row.status)], ["Pipeline stage", row.stage],
      ["Operations", row.operations.length ? row.operations.join(", ") : "-"], ["Technique", row.technique],
      ["Source", row.source_files.length ? bullets(row.source_files.map((f) => h("code", { text: f }))) : "-"],
      ["Benchmark examples", row.examples.length ? bullets(row.examples.map((e) => `${appName(e.app)}${e.query_ids.length ? `: ${e.query_ids.join(", ")}` : ""}`)) : "-"],
      ["Tests", row.tests.length ? bullets(row.tests.map((t) => h("code", { text: t }))) : "None"],
      ["Statements containing it (nine applications)", row.occurrences ? sourced(row.occurrences, "Occurrences") : "Not counted (not an SQL construct)"],
      ["By application", Object.keys(row.occurrences_by_app).length ? bullets(Object.entries(row.occurrences_by_app).map(([a, v]) =>
        [`${appName(a)}: `, sourced(v)])) : null],
      ["Limitation", row.limitation], ["Future improvement", row.future],
      ["Note", "Passing through the converter does not prove behavioural correctness."]]));
  }

  function renderMatrix(holder) {
    const rows = pp1().sql_matrix;
    const f = state.matrix;
    const ops = [...new Set(rows.flatMap((r) => r.operations))];
    const stages = [...new Set(rows.map((r) => r.stage))];
    const select = (label, key, options) => h("label", { class: "field" }, label, h("select", { "aria-label": label,
      onchange: (e) => { f[key] = e.target.value; render(); } },
    [["all", "All"], ...options].map(([v, t]) => h("option", { value: v, selected: v === f[key], text: t }))));
    const visible = rows.filter((r) => (f.status === "all" || r.status === f.status) && (f.stage === "all" || r.stage === f.stage)
      && (f.op === "all" || r.operations.includes(f.op)));
    const categories = [...new Set(visible.map((r) => r.category))];
    fill(holder,
      h("p", { class: "muted", text: "One status per SQL feature, from the implementation audit (docs/C3_PP1_audit_inventory.md) and checked against "
        + "the source when the data is generated. Statement counts come from parsing the stored recovered SQL of the nine applications. "
        + "Supported means C3 generates a function under its safety rules; it does not prove behavioural correctness." }),
      h("div", { class: "chip-row" }, Object.keys(pp1().statuses).map((k) => statusChip(k))),
      starWarningCard(),
      h("div", { class: "controls", style: "margin-bottom:var(--space-3)" },
        select("Support status", "status", Object.entries(pp1().statuses).map(([k, s]) => [k, s.label])),
        select("SQL operation", "op", ops.map((o) => [o, o])),
        select("Pipeline stage", "stage", stages.map((s) => [s, s]))),
      visible.length ? categories.map((cat) => {
        const inCat = visible.filter((r) => r.category === cat);
        return h("div", { class: "card" }, h("h3", { text: cat }),
          table(["SQL feature", "Status", "Stage", "Technique", "Example", "Statements (nine apps)", "Limitation"],
            inCat.map((r) => [r.feature, statusChip(r.status), r.stage, r.technique,
              r.examples.length ? r.examples.map((e) => `${appName(e.app)}${e.query_ids.length ? ` ${e.query_ids.join(", ")}` : ""}`).join("; ") : "-",
              r.occurrences ? sourced(r.occurrences, r.feature) : "-", r.limitation]),
            (i) => showMatrixRow(inCat[i])),
          h("p", { class: "muted", text: "Select a row for the source file, tests and future improvement." }));
      }) : h("p", { class: "empty", text: "No SQL feature matches these filters." }));
  }

  // Pipeline stages of the explorer; each reason or outcome is placed in exactly one.
  const EXPLORER_STAGES = [
    ["detection", "Detection", "Executor calls that cannot be analysed."],
    ["recovery", "SQL recovery", "Sites whose SQL text cannot be rebuilt safely."],
    ["parsing", "SQL parsing / representation", "Recovered text that is not a recognised CRUD statement or does not parse."],
    ["schema", "Schema mapping", "Sites that reference tables or columns missing from the supplied schema."],
    ["conversion", "Conversion", "Recovered SQL that no conversion rule accepts."],
    ["generation", "Code generation", "Every unresolved site gets a stub that raises instead of generated SQL; some generated functions are unverified."],
    ["security", "Security analysis", "Bounded injection check scope."],
    ["runtime", "Runtime / equivalence verification", "Behaviour checked on MySQL, or not."],
  ];
  const DETECTION_CODES = new Set(["UNSUPPORTED_EXECUTOR", "MISSING_SQL_ARGUMENT", "MULTI_STATEMENT_EXECUTOR"]);
  const reasonStage = (r) => (DETECTION_CODES.has(r.code) ? "detection" : r.code === "UNSUPPORTED_SHAPE" ? "parsing"
    : r.key === "CONVERSION_UNSUPPORTED:join_schema" ? "schema" : r.stage === "conversion" ? "conversion" : "recovery");
  const OUTCOME_STAGE = { schema_mismatch: "schema", unverified: "generation", verification_inconclusive: "runtime",
    failed_verification: "runtime", recoverable_unsupported: "conversion", non_recoverable: "recovery", ambiguous: "recovery", non_live: "detection" };

  function reasonCard(r) {
    const apps = Object.entries(r.by_app);
    return h("div", { class: "card reason-card" },
      h("h3", {}, h("code", { text: r.code }), r.key !== r.code ? h("span", { class: "muted", text: ` · ${r.key.split(":")[1].replace(/_/g, " ")}` }) : null),
      definitionList([
        ["Meaning", r.meaning], ["Recorded at stage", r.stage],
        ["Affected sites (nine applications)", sourced(r.count, `${r.code} sites`)],
        ["Query IDs", apps.length ? bullets(apps.map(([a, v]) => `${appName(a)}: ${v.query_ids.join(", ")}`)) : "-"],
        ["ams-native (separate)", r.ams_native ? [sourced(r.ams_native.count), ` · ${r.ams_native.query_ids.join(", ")}`] : null],
        ["Why it occurs", r.why], ["Code generated", r.code_generated], ["Manual review", r.review], ["Possible future solution", r.future]]));
  }

  function outcomeBlock(o) {
    const apps = Object.entries(o.apps).filter(([, v]) => v.count && v.count.value);
    return h("div", { class: "card" }, h("h3", { text: o.label }), h("p", { class: "sub", text: o.text }),
      apps.length ? table(["Application", "Sites", "Query IDs"], apps.map(([a, v]) => [appName(a), sourced(v.count, o.label),
        v.query_ids.length ? v.query_ids.join(", ") : "-"])) : h("p", { class: "muted", text: "None in the current evidence." }));
  }

  function renderExplorer(holder) {
    const p = pp1();
    const cat = p.reason_catalogue;
    fill(holder,
      h("p", { class: "muted", text: "Why sites abstain, fail or remain unverified, by pipeline stage. Reason codes and counts come from the "
        + "unresolved reports of the current-code run (nine applications); ams-native is listed separately from its committed record. "
        + "Different causes are kept apart, including the distinct causes behind STRUCTURAL." }),
      card("Reason codes in the source", null, definitionList([
        ["Recovery-stage codes defined", sourced(cat.defined_recovery)], ["Recovery-stage codes in use", sourced(cat.in_use_recovery)],
        ["Conversion-stage codes defined", sourced(cat.defined_conversion)], ["Conversion-stage codes in use", sourced(cat.in_use_conversion)],
        ["Codes", h("div", { class: "chip-row" }, cat.defined.map((c) => h("span", { class: `badge ${c.in_use ? "warn" : "derived"}`,
          text: `${c.code} (${c.stage}${c.in_use ? "" : ", not in use"})` })))]])),
      EXPLORER_STAGES.map(([key, title, text]) => {
        const reasons = p.reasons.filter((r) => reasonStage(r) === key);
        const unused = cat.defined.filter((c) => !c.in_use && key === "detection" && DETECTION_CODES.has(c.code));
        const outcomes = p.outcomes.filter((o) => OUTCOME_STAGE[o.key] === key);
        return h("section", { class: "explorer-stage" }, h("h3", { class: "stage-title", text: title }), h("p", { class: "sub", text }),
          reasons.map(reasonCard),
          unused.length ? h("p", { class: "muted", text: `Defined but not encountered: ${unused.map((c) => c.code).join(", ")}.` }) : null,
          key === "conversion" && p.template_overrides.length ? card("Converted despite a recovery code (query-specific templates)",
            "General recovery flags these Clinic sites; guarded templates for those exact files convert them. Reported separately, never as general rules.",
            table(["Recovery code", "Cause", "Sites", "Query IDs"], p.template_overrides.map((o) => [o.code, o.key.includes(":") ? o.key.split(":")[1].replace(/_/g, " ") : "-",
              sourced(o.count), Object.entries(o.query_ids).map(([a, q]) => `${appName(a)}: ${q.join(", ")}`).join("; ")]))) : null,
          key === "security" ? securityScope() : null,
          outcomes.map(outcomeBlock),
          !reasons.length && !outcomes.length && key !== "security" && !unused.length ? h("p", { class: "muted", text: "Nothing recorded at this stage in the current evidence." }) : null);
      }));
  }

  function securityScope() {
    const split = pp1().e4_split;
    return card("E4 bounded check: functions with and without runtime values",
      "Functions without a runtime value have no payload cases and pass trivially; they are not evidence of injection safety.",
      table(["Application", "Functions", "With runtime values (payloads bound or rejected)", "Without runtime values"],
        Object.entries(split).map(([a, v]) => [appName(a), sourced(v.functions), sourced(v.with_runtime_values), sourced(v.without_runtime_values)])));
  }

  function renderSql(root) {
    if (state.sqlView !== "sites") {
      const holder = h("div");
      fill(root,
        h("div", { class: "section-head" }, h("div", {}, h("h2", { text: state.sqlView === "matrix" ? "SQL Support Matrix (all applications)"
          : "Failure & Limitation Explorer (all applications)" }))),
        sqlViewSwitch(), holder);
      (state.sqlView === "matrix" ? renderMatrix : renderExplorer)(holder);
      return;
    }
    const records = DATA.records[state.app] || [];
    const filters = {
      all: () => true,
      converted: (r) => r.conversion_status === "CONVERTED",
      template: (r) => r.conversion_rule === "query_specific_template",
      unresolved_recovery: (r) => r.unresolved_stage === "recovery",
      unresolved_conversion: (r) => r.unresolved_stage === "conversion",
    };
    const filterSelect = h("select", { "aria-label": "Filter", onchange: (e) => { state.sqlFilter = e.target.value; render(); } },
      [["all", "All sites"], ["converted", "Converted"], ["template", "Converted by query-specific template"],
        ["unresolved_recovery", "Unresolved at recovery"], ["unresolved_conversion", "Unresolved at conversion"]]
        .map(([v, t]) => h("option", { value: v, selected: v === state.sqlFilter, text: t })));
    const searchBox = h("input", { type: "search", placeholder: "Filter by file, query ID or ground-truth ID", value: state.sqlSearch,
      oninput: (e) => { state.sqlSearch = e.target.value; renderSqlTable(); } });
    const holder = h("div");
    function renderSqlTable() {
      const q = state.sqlSearch.toLowerCase();
      const rows = records.filter(filters[state.sqlFilter]).filter((r) =>
        !q || `${r.file}:${r.line} ${r.query_id} ${r.gt_id || ""}`.toLowerCase().includes(q));
      fill(holder, rows.length ? table(
        ["Query ID", "Ground-truth ID", "PHP file:line", "Operation", "Recovery", "Conversion", "Unresolved reason", "Ground-truth label"],
        rows.map((r) => [r.query_id, r.gt_id || "-", h("code", { text: `${r.file}:${r.line}` }), r.operation || "-",
          r.recovery_status + (r.via_wrapper ? " (wrapper call)" : ""),
          r.conversion_status === "CONVERTED" ? `CONVERTED (${r.conversion_rule === "query_specific_template" ? "query-specific template" : "general rule"})` : "not converted",
          r.unresolved_stage ? `${r.unresolved_stage}: ${r.unresolved_reason_code}${r.unresolved_reason ? ` - ${r.unresolved_reason}` : ""}${r.join_kind ? ` (${r.join_kind})` : ""}` : "-",
          r.gt_label || "-"])) : h("p", { class: "empty", text: "No sites match this filter." }));
    }
    renderSqlTable();
    fill(root,
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: `SQL Results · ${DATA.apps[state.app].label}` }),
        h("p", { text: "One row per detected SQL execution site in the current-code run. Query IDs are C3's; ground-truth IDs come from "
          + "the author-verified ground truth, matched by file and line (they can differ). Recovered SQL text is not shown." }))),
      sqlViewSwitch(),
      state.app === "hms_kishan0725" ? h("div", { class: "notice", text: "HMS has no licence: reason text is withheld (codes only) and no SQL is shown." }) : null,
      h("div", { class: "controls", style: "margin-bottom:var(--space-3)" }, h("label", { class: "field" }, "Show", filterSelect),
        h("label", { class: "field" }, "Search", searchBox)),
      holder);
  }

  function renderModels(root) {
    const art = DATA.artifacts[state.app];
    const e2 = DATA.experiments.e2[state.app];
    const e3 = DATA.experiments.e3[state.app];
    const labels = { orm_classes: "ORM classes", core_tables: "Core tables (no primary key)", data_access_functions: "Data-access functions",
      unresolved_stubs: "Unresolved-site stubs", alembic_revisions: "Alembic revisions" };
    const verdict = (v) => h("span", { class: `badge ${v === "MATCH" || v === "PASS" ? "pass" : "warn"}`, text: v });
    fill(root,
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: `Models & Migration · ${DATA.apps[state.app].label}` }),
        h("p", { text: "Generated artifacts of the current-code run. File contents are not shown." }))),
      h("div", { class: "grid kpis" }, Object.entries(art.counts).map(([k, v]) =>
        h("div", { class: "kpi" }, h("div", { class: "kpi-label", text: labels[k] || k }), h("div", { class: "kpi-value", text: String(v) }),
          h("div", { class: "kpi-foot" }, statusBadge("derived"))))),
      h("p", { class: "muted", text: art.derivation }),
      h("div", { class: "grid two" },
        card("Generated files", "Present in the current-code run output.", table(["File", "Present"],
          Object.entries(art.files).map(([f, ok]) => [h("code", { text: f }), h("span", { class: `badge ${ok ? "good" : "bad"}`, text: ok ? "present" : "missing" })]))),
        card("Schema and migration verification", `E2 schema fidelity (${DATA.experiments.e2_dates.live}) and E3 Alembic round trip on MySQL (${DATA.experiments.e3_dates[state.app]}).`, table(["Check", "Result"], [
          ["E2 offline: original DDL (independent parse) vs C3 schema", verdict(e2.A_vs_B)],
          ["E2 offline: original DDL vs generated models", verdict(e2.A_vs_C)],
          ["E2 live: DDL loaded in MySQL and reflected vs models", verdict(e2.D_vs_C)],
          ["Query-vs-schema drift", e2.query_schema_drift],
          ["Tables / columns in the schema", `${e2.tables} / ${e2.columns}`],
          ["E3 round trip (upgrade, compare, check, downgrade)", verdict(e3.verdict)],
          ...Object.entries(e3.steps).map(([k, v]) => [`E3 step: ${k}`, verdict(v)]),
        ]))),
    );
  }

  // Migration Impact for the selected application (built by before_after.py from the current-code run).
  function renderImpact(root) {
    const ba = DATA.before_after;
    const app = DATA.apps[state.app];
    const payload = ba.apps[state.app];
    const body = h("div", { class: "mi-root" });
    fill(root,
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: `Migration Impact · ${app.label}` }),
        h("p", { class: "mi-subtitle", text: "From Embedded Legacy PHP SQL to Structured Python Data Access" }),
        h("p", { text: "Built from the current-code run of the selected application; every figure names its source file." }))),
      payload.detail ? null : h("div", { class: "notice info", text: ba.detail_policy }),
      body);
    MigrationImpact.render(body, payload, {
      label: app.label, role: payload.role, licence: payload.licence, verified: payload.verified_ground_truth,
      coverage: ba.coverage, coverageNote: ba.coverage_note, coverageSource: ba.coverage_source,
      countsOnlyText: `Code detail is not exported for ${app.label}. ${ba.detail_policy}`,
    });
  }

  // sqlacodegen schema-only baseline: model-file comparison counts from its summary.json (no query migration involved).
  function baselineCard() {
    const base = DATA.experiments.baseline;
    const rows = measurements((m) => m.category === "baseline" && m.metric !== "sqlacodegen_apps_compared").map((m) => {
      const t = base.totals[m.metric.replace("sqlacodegen_", "")];
      return [m.label.replace("sqlacodegen baseline: ", ""), t.compared,
        h("button", { type: "button", class: "button", onclick: () => showMeasurement(m), text: formatValue(m) }), t.differences];
    });
    return card("Schema-only baseline (sqlacodegen)",
      `Completed ${base.date}: sqlacodegen ${base.tool.sqlacodegen} models compared with the C3 models for ${base.apps_compared} of `
      + `${base.apps_total} applications; sqlacodegen failures: ${base.failures.length ? base.failures.join(", ") : "none"}.`,
      h("p", {}, statusBadge("measured"), " Counts summed from ", h("code", { text: base.file }), " (apps.<app>.comparison.counts). Method: ",
        h("code", { text: base.readme }), "."),
      table(["Property", "Compared", "Matches", "Differences"], rows),
      table(["Application", "Result", "Tables", "Columns", "Foreign keys compared"], Object.entries(base.apps).map(([id, a]) =>
        [appLabel(id), a.verdict, a.tables, a.columns, a.foreign_keys])),
      h("ul", {}, base.notes.map((t) => h("li", { text: t })),
        Object.entries(base.apps).flatMap(([id, a]) => a.notes.map((t) => h("li", { text: `${appLabel(id)}: ${t}` })))));
  }

  function renderEvaluation(root) {
    const hist = (metric) => measurements((m) => m.metric === metric && m.stage !== "current-code");
    const cur = (metric) => measurements((m) => m.metric === metric && m.stage === "current-code");
    const e4 = DATA.experiments.e4;
    const tests = DATA.experiments.tests;
    const notMeasured = measurements((m) => m.status === "not_measured");
    const columnRows = new Map();
    for (const m of measurements((x) => x.category === "column_use")) {
      const key = `${m.app}|${m.stage_label}`;
      if (!columnRows.has(key)) columnRows.set(key, { app: m.app, stage: m, cells: {} });
      columnRows.get(key).cells[m.metric.replace("column_use_", "")] = m;
    }
    const fields = ["operation", "tables", "read", "write", "filter"];
    const fr6 = DATA.limitations.find((l) => l.fr === "FR6");

    fill(root,
      h("div", { class: "section-head" }, h("div", {},
        h("h2", { text: "Evaluation" }),
        h("p", { text: "Each chart is one metric, grouped by application. Identical results at consecutive stages share a row; every stage "
          + "chip opens its own evidence (numerator/denominator, source file, related sites)." }))),
      h("div", { class: "notice info", text: DATA.disclosures.no_overall_score.text }),
      h("div", { class: "notice", text: DATA.disclosures.ground_truth.text }),
      definitionsCard(),
      card("Evaluation stages", null, stageLegend(), h("ul", {}, Object.entries(DATA.stage_definitions).map(([k, v]) =>
        h("li", {}, h("strong", { text: k }), ": ", v)))),
      card("SQL detection: detected live sites (not conversion)", "Ground-truth live sites that C3 detected (S15). This is detection only; conversion is a separate chart.",
        metricChart(hist("sql_detection"), { title: "SQL detection: detected live sites (not conversion)" })),
      card("Recovery precision", "Correct recoveries / all recoveries (S15; ambiguous sites excluded).",
        metricChart(hist("recovery_precision"), { title: "Recovery precision" })),
      card("Recovery recall", "Correct recoveries / recoverable sites (S15; ambiguous sites excluded).",
        metricChart(hist("recovery_recall"), { title: "Recovery recall" })),
      card("Correct abstentions", "Non-recoverable sites that C3 detected and flagged instead of guessing. Sites never detected are not counted.",
        metricChart(hist("correct_abstention"), { title: "Correct abstentions" })),
      card("Conversion coverage (current code)", "Ground-truth recoverable sites that became data-access functions. This is coverage, not recovery accuracy, and not behavioural equivalence.",
        metricChart([...cur("conversion_coverage_gt"), ...cur("general_rule_share")], {
          title: "Conversion coverage",
          label: (m) => (m.metric === "general_rule_share" ? "general rules only (code-derived)" : "recoverable converted"),
        }),
        h("div", { class: "notice", text: DATA.disclosures.clinic.text }),
        h("div", { class: "notice", text: DATA.disclosures.fee_rainbow.text })),
      card("Manual-review rate (current code)", DATA.manual_review.formula,
        metricChart(cur("manual_review_rate"), { title: "Manual-review rate", label: () => "live sites not converted" }),
        h("p", { class: "muted", text: DATA.manual_review.limits })),
      card("Execution time (current code)", `${DATA.experiments.performance.label}. ${DATA.experiments.performance.machine.cpu}, `
        + `${DATA.experiments.performance.machine.ram_gb} GB RAM, Python ${DATA.experiments.performance.machine.python}. One machine; not a benchmark of other hardware.`,
        table(["Application", "Runs (s)", "Median"], measurements((m) => m.metric === "execution_time").map((m) => [appLabel(m.app),
          DATA.experiments.performance.apps[m.app].runs_seconds.join(" · "),
          h("button", { type: "button", class: "button", onclick: () => showMeasurement(m), text: formatValue(m) })]))),
      card("E1 behavioural equivalence on MySQL", "Legacy PHP vs generated function on real MySQL, per SQL site (E1 harness). INCONCLUSIVE is not PASS.",
        e1Chart(),
        h("h4", { text: "Clinic MySQL verification (not E1)" }),
        table(["Application", "Tests passed", "Run", "Saved log"], DATA.experiments.e1.separate_suites.map((s) => {
          const m = measurement(s.app, "mysql_equivalence_tests_passed");
          return [appLabel(s.app), m ? h("button", { type: "button", class: "button", onclick: () => showMeasurement(m), text: `${s.passed} of ${s.collected}` })
            : `${s.passed} of ${s.collected}`, `${s.date}, MySQL ${s.mysql_server}`, h("code", { text: s.file })];
        })),
        h("p", { class: "muted", text: DATA.experiments.e1.separate_suites.map((s) => s.note).join(" ") }),
        h("p", { class: "muted" }, "Not measured with the E1 harness: ", measurements((m) => m.metric === "e1_equivalence").map((m) => appLabel(m.app)).join(", "),
          ". Conversion alone does not show equivalence.")),
      card("E4 injection negatives", `Recording-session check, ${e4.date_utc} (no database).`,
        metricChart(cur("e4_safe_functions"), { title: "E4", label: () => "functions SAFE", tone: "good" }),
        table(["Total", "Value"], [
          ["Functions tested", e4.totals.functions], ["SAFE", e4.totals.safe], ["UNSAFE", e4.totals.unsafe],
          ["Hostile cases", e4.totals.hostile_cases], ["Benign calls (derived)", e4.totals.benign_calls],
          ["Rejected cases", e4.totals.rejected], ["Payloads per function", e4.payload_count]]),
        h("h4", { text: "Limits of this check" }), h("ul", {}, e4.limitations.map((t) => h("li", { text: t })))),
      card("E2 schema fidelity and E3 Alembic round trip", `MySQL runs: E2 ${DATA.experiments.e2_dates.live}; E3 `
        + DATA.experiments.e3_runs.map((r) => `${r.date} (HEAD ${r.git_head_short}, ${r.pass} of ${r.apps} PASS${r.current ? ", current code, shown per application" : ", earlier run kept as history"})`).join("; ") + ".",
        metricChart(measurements((m) => m.category === "e2" || m.category === "e3"), {
          title: "E2/E3", label: (m) => (m.category === "e2" ? "E2: all schema views MATCH" : "E3: round trip PASS"), groupBy: () => "all" }),
        table(["Application", "E2 A–B", "E2 A–C", "E2 D–C", `E3 (${DATA.experiments.e3_runs.filter((r) => r.current).map((r) => r.date).join("")})`],
          Object.keys(DATA.apps).map((id) => [appLabel(id),
          DATA.experiments.e2[id].A_vs_B, DATA.experiments.e2[id].A_vs_C, DATA.experiments.e2[id].D_vs_C, DATA.experiments.e3[id].verdict]))),
      baselineCard(),
      card("Column-use accuracy", "Per SQL operation, against the ground truth. Select a cell for its source.",
        table(["Application", "Stage", ...fields], [...columnRows.values()].map((row) => [appLabel(row.app), stageBadge(row.stage),
          ...fields.map((f) => { const m = row.cells[f]; return m ? h("button", { type: "button", class: "button",
            onclick: () => showMeasurement(m), text: `${formatValue(m)} ${ratio(m)}` }) : "-"; })]))),
      h("div", { class: "grid two" },
        card("Regression tests (saved logs)", tests.note, table(["Run", "Date", "HEAD", "Passed", "Failed", "Skipped", "Saved log"],
          tests.runs.map((run) => {
            const cell = (metric) => {
              const m = measurements((x) => x.category === "tests" && x.stage_label === run.stage_label && x.metric === `${run.metric_prefix}_${metric}`)[0];
              return m ? h("button", { type: "button", class: "button", onclick: () => showMeasurement(m), text: formatValue(m) }) : "-";
            };
            return [run.latest ? run.title : `${run.title} (history)`, run.date || "-", h("code", { text: run.head_short }),
              cell("passed"), cell("failed"), cell("skipped"), h("code", { text: run.file })];
          }))),
        verificationScope(notMeasured)),
      card("Known limitations (FR2, FR4, FR6)", null, DATA.limitations.map((l) => h("div", { style: "margin-bottom:var(--space-3)" },
        h("strong", { text: `${l.fr}: ${l.title}. ` }), l.text, " ", h("span", { class: "muted" }, "Evidence: ", h("code", { text: l.evidence })))),
      table(["Join form", "Application", "Query ID", "Ground-truth ID", "PHP site", "Ground-truth label"],
        fr6.sites.map((s) => [s.join_kind, appLabel(s.app), s.query_id, s.gt_id || "-", h("code", { text: s.site }), s.gt_label || "-"]))),
    );
  }

  function renderReports(root) {
    const g = DATA.generated;
    fill(root,
      h("div", { class: "section-head" }, h("div", {}, h("h2", { text: "Reports" }),
        h("p", { text: "Verified report files in the repository. Only files served with this dashboard can be downloaded here." }))),
      table(["Report", "Path", "In repository", "Download"], DATA.reports.map((r) => [r.title, h("code", { text: r.path }),
        h("span", { class: `badge ${r.exists ? "good" : "bad"}`, text: r.exists ? "present" : "missing" }),
        r.downloadable && r.href ? h("a", { href: r.href, download: "", text: "Download" }) : h("span", { class: "muted", text: "Not served" })])),
      card("Data generation", null, definitionList([
        ["Generated by", h("code", { text: g.by })], ["Date", g.date], ["Git HEAD", h("code", { text: g.git_head })],
        ["Current-code run", g.current_code_run]])),
    );
  }

  // ---------- shell ----------
  function selectApp(id) {
    state.app = id;
    document.getElementById("app-select").value = id;
    render();
  }

  function render() {
    if (!DATA) return;
    for (const id of SECTIONS) {
      document.getElementById(`section-${id}`).hidden = id !== state.section;
      const tab = document.querySelector(`.sub-tab[data-section="${id}"]`);
      tab.setAttribute("aria-selected", String(id === state.section));
    }
    document.getElementById("app-controls").hidden = !APP_SCOPED.has(state.section) || (state.section === "sql" && state.sqlView !== "sites");
    const root = document.getElementById(`section-${state.section}`);
    ({ functions: renderFunctions, overview: renderOverview, sql: renderSql, models: renderModels, impact: renderImpact,
      evaluation: renderEvaluation, reports: renderReports })[state.section](root);
  }

  function setSection(section) {
    const name = section === "before-after" ? "impact" : section;  // old links to the earlier Before / After tab
    state.section = SECTIONS.includes(name) ? name : "functions";
    render();
  }

  async function init() {
    const status = document.getElementById("load-status");
    try {
      const response = await fetch("data/dashboard_data.json", { cache: "no-store" });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      DATA = await response.json();
    } catch (error) {
      status.className = "notice error";
      status.textContent = `Could not load data/dashboard_data.json (${error.message}). Serve this folder over HTTP, for example: `
        + "python -m http.server --directory components/c3_data_layer/dashboard";
      return;
    }
    status.hidden = true;
    const select = document.getElementById("app-select");
    select.replaceChildren(...Object.values(DATA.apps).map((a) => h("option", { value: a.id, text: `${a.label} - ${a.role}` })));
    select.addEventListener("change", (e) => selectApp(e.target.value));
    state.app = Object.keys(DATA.apps)[0];
    document.getElementById("footer").textContent =
      `C3 Migration Studio · evidence generated ${DATA.generated.date} at ${DATA.generated.git_head.slice(0, LAYOUT.shortHash)}`;
    document.getElementById("detail-close").addEventListener("click", closeDrawer);
    document.getElementById("scrim").addEventListener("click", closeDrawer);
    document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeDrawer(); });
    render();
  }

  return { init, setSection, closeDrawer };
})();
/* ===== END EVIDENCE ===== */

/* ===== MIGRATION IMPACT (renders one payload passed in; reads no global data) ===== */
// Payload: components/c3_data_layer/dashboard/before_after.py build() for one C3 run (plus, on the evidence tab, the
// app's own verification evidence). Every number shown is read from the payload; nothing is computed beyond sums.
const MigrationImpact = (() => {
  const show = (v) => (v === null || v === undefined || v === "" ? "-" : v);
  const count = (n, one, many) => `${n} ${n === 1 ? one : many}`;
  const NA = "N/A - No applicable cases identified";
  const ofText = (v, of) => (v === null || v === undefined ? "Not measured"
    : of === null || of === undefined ? String(v) : of === 0 && v === 0 ? NA : `${v} of ${of}`);
  const grid = (headers, rows, cls) => h("div", { class: "table-wrap" }, h("table", { class: cls || null },
    h("thead", {}, h("tr", {}, headers.map((x) => h("th", { scope: "col", text: x })))),
    h("tbody", {}, rows.map((cells) => h("tr", {}, cells.map((c) => h("td", {}, show(c))))))));
  const icon = (name) => h("span", { class: `mi-icon ${name}`, "aria-hidden": "true" });
  const step = (title, sub, iconName, ...children) => h("section", { class: "card mi-step" },
    h("h3", {}, icon(iconName), h("span", { class: "mi-step-no", "aria-hidden": "true" }), title),
    sub ? h("p", { class: "sub", text: sub }) : null, children);
  const KIND = { measured: ["measured", "Measured"], design: ["design", "Design property"], none: ["warn", "Not measured"] };
  const chip = (kind) => h("span", { class: `badge ${KIND[kind][0]}`, text: KIND[kind][1] });
  const code = (text, pattern, cls) => {
    const node = h("code", {});
    if (!text) return node;
    let last = 0;
    for (const m of pattern ? text.matchAll(pattern) : []) {
      node.append(text.slice(last, m.index), h("mark", { class: cls, text: m[0] }));
      last = m.index + m[0].length;
    }
    node.append(text.slice(last));
    return node;
  };
  const pre = (text, pattern, cls) => h("pre", { class: "code-preview mi-code" }, code(text, pattern, cls));
  const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const bindPattern = (keys) => (keys && keys.length ? new RegExp(`:(?:${keys.map(escapeRe).join("|")})\\b`, "g") : null);
  const PHP_VALUE = /\{\{\w+\}\}/g;

  // ---------- 1. overview ----------
  function overview(p, opt) {
    const f = p.facts;
    const kpi = (label, value, foot, extra) => h("div", { class: "kpi mi-kpi" },
      h("div", { class: "kpi-label", text: label }), h("div", { class: "kpi-value", text: String(value) }),
      h("div", { class: "kpi-foot" }, foot), extra || null);
    const topReasons = p.limitations.map((l) => `${l.code} ${l.count}`).join(", ");
    return step("Migration Impact Overview", null, "overview",
      h("div", { class: "mi-app-head" },
        h("strong", { text: opt.label }),
        opt.role ? h("span", { class: "badge", text: opt.role }) : null,
        opt.verified === true ? h("span", { class: "badge measured", text: "author-verified ground truth" })
          : opt.verified === false ? h("span", { class: "badge warn", text: "no ground truth: pipeline counts" }) : null,
        opt.licence ? h("span", { class: "muted", text: `Licence / provenance: ${opt.licence}` }) : null),
      h("div", { class: "grid kpis mi-kpis" },
        kpi("SQL operations analysed", f.detected, `detected SQL sites · ${f.recovered} recovered · in ${count(f.php_files, "PHP file", "PHP files")}`),
        kpi("Automatically generated functions", f.converted,
          `general rules ${f.general_rules} · query-specific templates ${f.templates}`,
          h("div", {}, coverageBar(f), h("div", { class: "kpi-foot", text: `${f.converted} of ${f.detected} detected sites converted` }))),
        kpi("Parameterized data access", f.functions_with_bind_parameters,
          `of ${f.data_access_functions} generated functions take bound runtime parameters (${f.bind_parameters} in total)`,
          h("div", { class: "kpi-foot", text: `Confirmed legacy injection sites remediated: ${ofText(f.legacy_injection_sites_remediated, f.legacy_injection_sites)}` })),
        kpi("Manual review required", f.unresolved,
          `recovery stage ${f.unresolved_recovery} · conversion stage ${f.unresolved_conversion}`,
          topReasons ? h("div", { class: "kpi-foot", text: `Reason codes: ${topReasons}` }) : null)),
      h("p", { class: "muted mi-fine", text: p.coverage_note }));
  }

  function coverageBar(row) {
    const parts = [["converted", row.converted, "converted"], ["conversion", row.unresolved_conversion, "recovered, not converted"],
      ["recovery", row.unresolved_recovery, "not recovered"]];
    return h("div", { class: "mi-bar", role: "img",
      "aria-label": parts.map(([, n, t]) => `${t} ${n}`).join(", ") + ` of ${row.detected} detected` },
      parts.filter(([, n]) => n > 0).map(([cls, n, t]) =>
        h("span", { class: `mi-seg ${cls}`, style: `flex-grow:${n}`, title: `${t}: ${n} of ${row.detected}` })));
  }

  // ---------- 2. explorer ----------
  function explorer(p, opt) {
    const queries = p.queries;
    const holder = h("div", {});
    const preferred = queries.find((q) => q.status === "converted" && q.security.legacy_injection_site)
      || queries.find((q) => q.status === "converted" && q.function && q.function.bind_keys.length) || queries[0];
    const select = h("select", { "aria-label": "SQL site", onchange: (e) => draw(queries[Number(e.target.value)]) },
      queries.map((q, i) => h("option", { value: String(i), selected: q === preferred ? true : null,
        text: `${q.query_id} · ${q.site} · ${q.status === "converted" ? "converted" : `flagged (${q.flag ? q.flag.reason_code : "-"})`}` })));
    function draw(q) {
      const fn = q.function;
      const left = h("div", { class: "mi-panel before" },
        h("div", { class: "mi-panel-head" }, h("span", { class: "mi-tag before", text: "BEFORE" }), h("strong", { text: "Legacy PHP data access" })),
        h("dl", { class: "mi-facts" },
          h("dt", { text: "Application" }), h("dd", { text: opt.label }),
          h("dt", { text: "PHP file:line" }), h("dd", {}, h("code", { text: q.site })),
          h("dt", { text: "Query ID" }), h("dd", { text: q.query_id }),
          h("dt", { text: "Executor" }), h("dd", {}, h("code", { text: show(q.executor) })),
          h("dt", { text: "Operation" }), h("dd", { text: show(q.operation) })),
        q.php_line ? [h("h4", { text: `PHP source line (verbatim, line ${q.site.split(":").pop()})` }), pre(q.php_line)] : null,
        h("h4", { text: "Recovered SQL (reconstructed by C3, not verbatim source)" }),
        q.legacy_sql ? pre(q.legacy_sql, PHP_VALUE, "mi-mark-php") : h("p", { class: "muted", text: "C3 could not recover the SQL text for this site." }),
        q.dynamic_values.length ? h("p", { class: "mi-fine" }, "PHP values interpolated into the SQL text: ",
          q.dynamic_values.map((v) => h("mark", { class: "mi-mark-php", text: `{{${v}}}` })), ` (${q.dynamic_values.length})`) : null);
      const right = h("div", { class: "mi-panel after" },
        h("div", { class: "mi-panel-head" }, h("span", { class: "mi-tag after", text: "AFTER" }),
          h("strong", { text: q.status === "converted" ? "Generated Python data access" : "Flagged for manual review" })),
        q.status === "converted" && fn ? [
          h("dl", { class: "mi-facts" },
            h("dt", { text: "Function" }), h("dd", {}, h("code", { text: `data_access.${fn.name}` })),
            h("dt", { text: "Rule" }), h("dd", { text: q.conversion_rule === "query_specific_template" ? "query-specific template" : "general rule" }),
            h("dt", { text: "Returns" }), h("dd", { text: fn.returns }),
            h("dt", { text: "Traceability" }), h("dd", {}, fn.cited_site ? h("code", { text: `docstring cites ${fn.cited_site}` })
              : h("span", { text: "site recorded in traceability_report.json (docstring does not cite it)" }))),
          h("h4", { text: "Generated function (exact excerpt of data_access.py)" }),
          fn.code ? pre(fn.code, bindPattern(fn.bind_keys), "mi-mark-bind") : null,
          fn.parameter_mapping.length ? [h("h4", { text: "Parameter mapping (PHP value → bound parameter)" }),
            grid(["PHP value at the call", "Bound as"], fn.parameter_mapping.map((m) => [h("code", { text: m.php_value }), h("code", { text: `:${m.parameter}` })]))]
            : h("p", { class: "muted", text: "This function takes no runtime value." }),
          q.model ? h("p", { class: "mi-fine" }, "Table ", h("code", { text: q.table }), " → ", h("code", { text: q.model.name }), " ",
            h("span", { class: `badge ${q.model.kind.startsWith("Core") ? "warn" : "good"}`, text: q.model.kind })) : null,
        ] : [
          h("dl", { class: "mi-facts" },
            h("dt", { text: "Reason code" }), h("dd", {}, h("span", { class: "badge warn", text: q.flag ? q.flag.reason_code : "-" })),
            h("dt", { text: "Stage" }), h("dd", { text: q.flag ? q.flag.stage : "-" }),
            h("dt", { text: "Reason" }), h("dd", { text: q.flag ? show(q.flag.reason) : "-" }),
            h("dt", { text: "Action" }), h("dd", { text: q.flag ? show(q.flag.action) : "-" }),
            h("dt", { text: "Generated" }), h("dd", {}, fn ? [h("code", { text: fn.name }), " (a stub that raises NotImplementedError; no SQL is generated)"] : "nothing")),
        ]);
      fill(holder, h("div", { class: "mi-code-grid" }, left, h("div", { class: "mi-arrow", "aria-hidden": "true", text: "→" }), right), callouts(q));
    }
    draw(preferred);
    return step("Real Code Transformation Explorer", "Choose a detected SQL site. Left: what C3 found in the PHP. Right: what C3 generated for that exact site (mapped through traceability_report.json).",
      "explorer", h("label", { class: "field mi-select" }, "SQL site", select), holder);
  }

  function callouts(q) {
    const fn = q.function;
    const sec = q.security;
    const user = sec.values.filter((v) => v.user_controlled);
    const a = q.status !== "converted" ? "Not converted, so no parameters were generated for this site."
      : fn && fn.bind_keys.length
        ? `${fn.bind_keys.length} value(s) are passed as bound parameters (${fn.bind_keys.map((k) => `:${k}`).join(", ")}) instead of being written into the SQL text. `
          + (sec.legacy_injection_site
            ? `The security report classifies this site as a legacy injection site and marks it ${sec.remediated ? "remediated" : "not remediated"}. Traced sources (may pass through a query result): ${user.map((v) => `${v.variable} from ${v.sources.join("/")}`).join(", ")}.`
            : "The security report does not classify this site as a confirmed legacy injection site, so no remediation claim is made.")
        : "This query takes no runtime value; there is nothing to bind.";
    const b = q.status === "converted" && fn
      ? `The embedded ${show(q.executor)} call at ${q.site} is available as ${fn.name}() in data_access.py${fn.cited_site ? `, whose docstring cites ${fn.cited_site}` : ""}.`
      : `No function was generated; the site is listed in unresolved_queries.json with reason ${q.flag ? q.flag.reason_code : "-"} for manual review.`;
    const c = q.model ? `The table ${q.table} is represented as ${q.model.kind === "ORM class" ? "the ORM class" : "the SQLAlchemy Core Table"} ${q.model.name}${q.model.relationships.length ? ` with ${q.model.relationships.length} relationship attribute(s)` : ""}. The database itself is not redesigned.`
      : "No single target table is recorded for this site (see the schema section below).";
    const box = (letter, title, text) => h("div", { class: "mi-callout" }, h("div", { class: "mi-callout-head" }, h("span", { class: "mi-letter", text: letter }), h("strong", { text: title })), h("p", { text }));
    return h("div", { class: "mi-callouts" },
      box("A", "Dynamic SQL values → bound parameters", a),
      box("B", "Embedded database call → generated function", b),
      box("C", "Database schema → SQLAlchemy model", c));
  }

  // ---------- 3. scoreboard ----------
  function scoreboard(p) {
    const f = p.facts;
    const card = (title, kind, before, after, benefit, measured, iconName) => h("div", { class: "mi-score" },
      h("div", { class: "mi-score-head" }, icon(iconName), h("strong", { text: title }), chip(kind)),
      h("div", { class: "mi-flow" },
        h("div", {}, h("span", { class: "mi-tag before", text: "BEFORE" }), h("p", { text: before })),
        h("span", { class: "mi-arrow small", "aria-hidden": "true", text: "→" }),
        h("div", {}, h("span", { class: "mi-tag after", text: "AFTER" }), h("p", { text: after }))),
      h("p", { class: "mi-benefit" }, h("strong", { text: "Developer benefit: " }), benefit),
      h("p", { class: "mi-fine muted" }, h("strong", { text: "Measurement: " }), measured));
    return step("Before → After Improvement Scoreboard", null, "score", h("div", { class: "mi-scores" },
      card("SQL locality", "measured", `${count(f.detected, "SQL site", "SQL sites")} spread across ${count(f.php_files, "PHP source file", "PHP source files")}.`,
        `${count(f.data_access_functions, "generated function", "generated functions")} in one module, data_access.py.`,
        "Supported database operations sit in one generated layer, which makes the migration easier to review. No maintenance-time saving is claimed.",
        "distinct source_file values in queries.json; data-access functions listed in traceability_report.json.", "files"),
      card("Parameterization", "measured", `${f.dynamic_value_sites} of ${f.detected} sites build SQL text from PHP values (recovered as {{name}}).`,
        `${f.bind_parameters} named bind parameters across ${f.functions_with_bind_parameters} generated functions. Confirmed legacy injection sites remediated: ${ofText(f.legacy_injection_sites_remediated, f.legacy_injection_sites)}.`,
        "Runtime values are handled as bound parameters instead of being interpolated into SQL text.",
        "dynamic_variables in queries.json; bind keys in data_access.py; security_report.json summary.", "shield"),
      card("Schema representation", "measured", `${f.tables} MySQL tables, ${f.columns} columns, ${f.tables_with_primary_key} with a primary key, ${f.foreign_keys} declared foreign keys.`,
        `${f.orm_classes} ORM classes, ${f.core_tables} Core Tables (no primary key), ${f.relationships} relationship attributes.`,
        "The existing schema is available as structured Python models. The database is not redesigned.",
        "schema.json; class and Table definitions in models.py.", "table"),
      card("Traceability", "measured", `${f.detected} SQL sites located at a PHP file:line.`,
        `${ofText(f.traceable_sites, f.trace_entries)} sites mapped in traceability_report.json; ${ofText(f.functions_citing_site, f.data_access_functions)} generated functions cite their site in the docstring.`,
        "Each generated function can be audited against the PHP it replaces.",
        "traceability_report.json; 'Migrated from <file>:<line>' docstrings in data_access.py. The two counts differ by definition.", "link"),
      card("Manual review", "measured", `${count(f.unresolved, "site", "sites")} C3 could not convert safely.`,
        `${count(f.unresolved, "site", "sites")} reported with a reason code (recovery ${f.unresolved_recovery}, conversion ${f.unresolved_conversion}); stubs raise NotImplementedError.`,
        "Migration gaps are visible instead of being guessed. These sites are not migrated.",
        "unresolved_queries.json; summary.json unresolved_total.", "flag")));
  }

  // ---------- 4. structural comparison ----------
  function structural(p, verification, opt) {
    const live = Boolean(opt && opt.live);
    const f = p.facts;
    const v = verification || {};
    const e1 = v.e1 ? `E1: PASS ${v.e1.verdicts.PASS}, FAIL ${v.e1.verdicts.FAIL}, INCONCLUSIVE ${v.e1.verdicts.INCONCLUSIVE} of ${v.e1.sites} sites`
      : v.mysql_suite ? `Clinic MySQL verification (not E1): ${v.mysql_suite.passed} of ${v.mysql_suite.collected} tests passed` : "Not measured for this application";
    const security = v.e4 ? `Security report: ${f.generated_code_violations} generated-code violations; E4: ${v.e4.safe} of ${v.e4.functions} functions SAFE (bounded check)`
      : `Security report: ${f.generated_code_violations} generated-code violations; E4: not measured`;
    const rows = [
      ["SQL dispersion across PHP source files", `${count(f.detected, "site", "sites")} in ${count(f.php_files, "file", "files")}`, `${f.data_access_functions} functions in data_access.py`, "queries.json, traceability_report.json", chip("measured")],
      ["Data-access module organisation", "SQL built and executed inside PHP pages and functions", "One generated module; one function per converted site, named after operation, table and query ID", "data_access.py structure", chip("design")],
      ["Runtime parameter representation", `${f.dynamic_value_sites} sites interpolate PHP values into SQL text`, `${f.bind_parameters} named bind parameters`, "queries.json dynamic_variables; data_access.py bind keys", chip("measured")],
      ["Database table representation", `${f.tables} tables, ${f.columns} columns`, `${f.orm_classes} ORM classes, ${f.core_tables} Core Tables`, "schema.json, models.py", chip("measured")],
      ["Primary / foreign key handling", `${f.tables_with_primary_key} tables with a primary key; ${f.foreign_keys} declared foreign keys`, `${f.relationships} relationship attributes from declared foreign keys; tables without a key become Core Tables`, "schema.json, models.py", chip("measured")],
      ["Query source traceability", `${f.detected} sites at PHP file:line`, `${ofText(f.traceable_sites, f.trace_entries)} mapped; ${ofText(f.functions_citing_site, f.data_access_functions)} docstrings cite the site`, "traceability_report.json, data_access.py", chip("measured")],
      ["Unresolved-query visibility", "Not reported by the legacy code", `${f.unresolved} sites with reason codes and stage`, "unresolved_queries.json", chip("measured")],
      // A live upload has no E1, MySQL or E4 run: those rows are left out (see "Scope of this live run").
      live ? null : ["Security checks", `Confirmed legacy injection sites: ${ofText(f.legacy_injection_sites, null)}`, security, "security_report.json; E4 report", chip(v.e4 ? "measured" : "none")],
      live ? null : [v.e1 ? "Behavioural equivalence" : "MySQL verification", "-", e1, v.e1 ? v.e1.source : v.mysql_suite ? v.mysql_suite.source : "-", chip(v.e1 || v.mysql_suite ? "measured" : "none")],
    ].filter(Boolean);
    return step("Structural Comparison & Maintainability", "Static structural counts only. No cyclomatic complexity, maintainability index, cognitive complexity or lines-of-code comparison is shown: the two codebases have not been measured with a comparable method.",
      "layers", grid(["Attribute", "Before: legacy PHP", "After: C3 SQLAlchemy", "Evidence / calculation", "Classification"], rows, "mi-matrix"));
  }

  // ---------- 5. benefits matrix ----------
  function benefitsMatrix(p, verification, opt) {
    const live = Boolean(opt && opt.live);
    const f = p.facts;
    const v = verification || {};
    const verify = [v.e1 ? `E1 (this app): PASS ${v.e1.verdicts.PASS} / FAIL ${v.e1.verdicts.FAIL} / INCONCLUSIVE ${v.e1.verdicts.INCONCLUSIVE} of ${v.e1.sites}` : null,
      v.mysql_suite ? `Clinic MySQL verification (not E1): ${v.mysql_suite.passed} of ${v.mysql_suite.collected}` : null,
      v.e4 ? `E4 (this app): ${v.e4.safe} of ${v.e4.functions} SAFE with ${v.e4.payload_count} fixed payloads, MySQL SQL compilation, no database executed; not a general proof of injection safety` : null]
      .filter(Boolean).join(". ") || "Not measured for this run";
    const rows = [
      ["Security-related transformation", "Dynamic values written into SQL text", "Parameterized SQLAlchemy text() with named binds", "Values are bound, not interpolated",
        `${f.bind_parameters} bind parameters; confirmed legacy injection sites remediated ${ofText(f.legacy_injection_sites_remediated, f.legacy_injection_sites)}`, chip("measured")],
      ["Automation", "Rewriting each data-access call by hand", "Generated functions for supported SQL", "Less manual rewriting for supported sites",
        `${f.converted} of ${f.detected} detected sites converted`, chip("measured")],
      ["Structural organisation", "SQL embedded in procedural PHP", "A generated Python data-access layer", "One place to review database access",
        `${f.php_files} PHP files → 1 module (${f.data_access_functions} functions)`, chip("measured")],
      ["Schema mapping", "Legacy MySQL schema", "SQLAlchemy ORM classes and Core Tables", "Typed Python models of the existing schema",
        `${f.orm_classes} ORM, ${f.core_tables} Core, ${f.relationships} relationships`, chip("measured")],
      ["Traceability", "Query locations scattered in PHP", "Source-to-function mapping", "Auditable migration",
        `${ofText(f.traceable_sites, f.trace_entries)} sites mapped`, chip("measured")],
      ["Reviewability", "Complex unsupported SQL", "Unresolved-query report with reasons", "Gaps are explicit",
        `${f.unresolved} sites with reason codes`, chip("measured")],
      live ? null : ["Verification", "Migrated behaviour unverified", "App-specific E1 / MySQL tests and bounded E4 where run", "Evidence instead of assumption", verify,
        chip(v.e1 || v.mysql_suite || v.e4 ? "measured" : "none")],
    ].filter(Boolean);
    return step("Migration Benefits Matrix", null, "matrix",
      grid(["Category", "Legacy difficulty", "C3 transformation", "Benefit", "Supporting measurement", "Evidence type"], rows, "mi-matrix"));
  }

  // ---------- 6. coverage ----------
  function coverage(rows, note, source) {
    const legend = h("div", { class: "mi-legend" },
      [["converted", "Converted to a generated function"], ["conversion", "Recovered, not converted"], ["recovery", "Not recovered"]]
        .map(([cls, t]) => h("span", {}, h("span", { class: `mi-swatch ${cls}` }), t)));
    const chart = h("div", { class: "mi-coverage" }, rows.map((r) => h("div", { class: "mi-cov-row" },
      h("span", { class: "mi-cov-label", text: r.label }),
      r.detected ? coverageBar(r) : h("span", { class: "muted", text: "Not available" }),
      h("span", { class: "mi-cov-value", text: r.detected ? `${r.converted} of ${r.detected}` : "-" }))));
    const table = h("details", { class: "mi-details" }, h("summary", { text: "Show as table" }),
      grid(["Application", "Detected sites", "Converted", "of which templates", "Recovered, not converted", "Not recovered"],
        rows.map((r) => [r.label, r.detected, r.converted, r.templates, r.unresolved_conversion, r.unresolved_recovery])));
    return step("Application Coverage Comparison", note, "chart", legend, chart, table,
      source ? h("p", { class: "mi-fine muted" }, "Source: ", h("code", { text: source })) : null);
  }

  // ---------- 7. limitations ----------
  function limitations(p) {
    if (!p.limitations.length) return step("Limitations & Manual Review", null, "flag", h("p", { class: "muted", text: "No site of this run was flagged for manual review." }));
    return step("Limitations & Manual Review", "Reason codes from unresolved_queries.json. Proposed improvements are future work and are not implemented.", "flag",
      h("div", { class: "mi-limits" }, p.limitations.map((l) => h("div", { class: "mi-limit" },
        h("div", { class: "mi-score-head" }, h("span", { class: "badge warn", text: l.code }), h("strong", { text: l.category }),
          h("span", { class: "mi-count", text: count(l.count, "site", "sites") })),
        h("p", { class: "mi-fine" }, h("strong", { text: "Stage: " }), Object.entries(l.stages).map(([s, n]) => `${s} ${n}`).join(", ")),
        h("p", { text: l.why }),
        l.reasons.length ? h("ul", { class: "ba-list" }, l.reasons.map((r) => h("li", { class: "muted", text: r }))) : null,
        h("p", { class: "mi-fine" }, h("strong", { text: `${l.future_work_status}: ` }), l.future_work)))));
  }

  // ---------- 8. technical evidence ----------
  function evidence(p, opt) {
    // The E4 item of a live upload is "not measured" in the data; the live view leaves the row out.
    const rows = p.benefits.filter((b) => !(opt.live && b.key === "e4")).map((b) => [
      h("span", {}, b.label, b.note ? h("div", { class: "muted", text: b.note }) : null),
      ofText(b.value, b.of),
      b.source && b.source.file ? h("span", {}, h("code", { text: b.source.file }), b.source.field || b.source.derivation ? ` · ${b.source.field || b.source.derivation}` : "") : "not measured"]);
    return h("details", { class: "card mi-details mi-evidence" },
      h("summary", {}, icon("source"), h("span", { class: "mi-step-no", "aria-hidden": "true" }), h("strong", { text: "Technical Evidence & Sources" })),
      h("p", { class: "sub", text: p.note }),
      grid(["Measured property", "Value", "Source"], rows),
      h("h4", { text: "Definitions" }),
      h("ul", { class: "ba-list" },
        h("li", { text: "Functions with runtime bind parameters: generated functions whose code binds at least one named parameter." }),
        h("li", { text: "User-controlled values: values the security report traces to a request superglobal (see below)." }),
        h("li", { text: "Confirmed legacy injection sites: sites where a user-controlled value reaches the legacy SQL text unsafely (security report)." }),
        h("li", { text: "E4: a separate bounded check of the generated functions with fixed payloads; it is not run on uploads." }),
        p.explanations.map((t) => h("li", { text: t }))),
      opt.sourcesNote ? h("p", { class: "mi-fine muted", text: opt.sourcesNote }) : null);
  }

  // Live uploads are analysed statically; the offline evaluations are on the Evaluation tab.
  function liveScope() {
    return h("div", { class: "notice info mi-live-scope" }, h("strong", { text: "Scope of this live run" }), h("p", {},
      "This upload is analysed statically: conversion coverage, parameterization, traceability and structure are computed from its output. "
      + "Behavioural equivalence (E1), the injection payload check (E4) and Alembic round trips (E2/E3) are separate offline evaluations on the "
      + "benchmark applications; see the ", h("a", { href: "#/evidence/evaluation", text: "Evaluation tab" }), "."));
  }

  function render(root, payload, options) {
    const opt = options || {};
    const rows = opt.coverage || [{ label: opt.label, detected: payload.facts.detected, converted: payload.facts.converted,
      templates: payload.facts.templates, unresolved_conversion: payload.facts.unresolved_conversion, unresolved_recovery: payload.facts.unresolved_recovery }];
    fill(root,
      overview(payload, opt),
      payload.detail ? explorer(payload, opt)
        : step("Real Code Transformation Explorer", null, "explorer", h("div", { class: "notice", text: opt.countsOnlyText || "Counts only for this application." })),
      scoreboard(payload),
      opt.live ? liveScope() : null,
      structural(payload, payload.verification, opt),
      benefitsMatrix(payload, payload.verification, opt),
      coverage(rows, opt.coverageNote || payload.coverage_note, opt.coverageSource),
      limitations(payload),
      evidence(payload, opt));
  }
  return { render };
})();
/* ===== END MIGRATION IMPACT ===== */

/* ===== TRY IT (no evidence data) ===== */
const TryIt = (() => {
  // Talks only to the local bridge (server.py, /api/...) and to the recorded
  // sample file. It never reads the evidence data, so benchmark results can never
  // appear as results of an uploaded project, and it never computes a percentage:
  // uploads have no ground truth.
  const API = "/api/";
  const SAMPLE = "data/sample_run.json";
  const $ = (id) => document.getElementById(id);
  const state = { connected: false, busy: false, run: null, source: null, previews: {}, timer: null };

  async function getJson(url, options) {
    const response = await fetch(url, Object.assign({ cache: "no-store" }, options || {}));
    let body = null;
    try { body = await response.json(); } catch (error) { body = null; }
    if (!response.ok) {
      const error = new Error((body && body.error) || `Request failed (HTTP ${response.status}).`);
      error.detail = body || {};
      throw error;
    }
    return body;
  }

  const megabytes = (bytes) => Math.round(bytes / (LAYOUT.bytesPerKb * LAYOUT.bytesPerKb));
  const chosen = (id) => { const input = $(id); return input.files && input.files[0] ? input.files[0] : null; };

  function describe(input, target) {
    const file = input.files && input.files[0];
    target.textContent = file
      ? `${file.name} (${Math.max(1, Math.round(file.size / LAYOUT.bytesPerKb))} KB) selected. It stays on this computer.`
      : "No file selected.";
    updateButton();
  }

  function updateButton() {
    const run = $("run-migration");
    run.textContent = state.connected ? (state.busy ? "Analysing…" : "Analyze & Generate Data Layer") : "Local migration connection pending";
    const ready = state.connected && !state.busy && chosen("php-zip") && chosen("schema-sql");
    run.disabled = !ready;
    run.setAttribute("aria-disabled", String(!ready));
    $("load-sample").disabled = state.busy;
  }

  function showError(message) { $("tryit-error").textContent = message; $("tryit-error").hidden = !message; }

  // A failed C3 run: stage, exception, where in C3, the generated line if any, who is at fault, and the kept log.
  function showFailure(error) {
    const failure = error.detail && error.detail.failure;
    if (!failure) return showError(error.message);
    const rows = [
      ["Stage", failure.stage],
      ["Error", `${failure.exception}: ${failure.message}`],
      ["Where in C3", failure.frame],
      ["Generated code", failure.generated_code ? `line ${failure.generated_code.line}: ${failure.generated_code.code}` : null],
    ].filter(([, value]) => value);
    fill($("tryit-error"),
      h("p", { class: "failure-head" }, h("strong", { text: "C3 could not finish this upload. " }),
        `This is ${failure.classification_text}.`),
      h("dl", { class: "failure-detail" }, rows.map(([k, v]) => [h("dt", { text: k }), h("dd", {}, h("code", { text: v }))])),
      error.detail.log_url ? h("p", {}, h("a", { href: error.detail.log_url, download: "", text: "Download the run log" }),
        " (kept on this computer until the hourly cleanup; paths are shown relative to your upload).") : null);
    $("tryit-error").hidden = false;
    return null;
  }

  function progress(message) {
    const box = $("tryit-progress");
    box.textContent = message || "";
    box.hidden = !message;
  }

  function startTimer() {
    const started = Date.now();
    progress("Uploading and running C3 on your project…");
    state.timer = setInterval(() => {
      progress(`Running C3 on your project… ${Math.floor((Date.now() - started) / LAYOUT.msPerSecond)} s elapsed`);
    }, LAYOUT.msPerSecond);
  }
  function stopTimer() { clearInterval(state.timer); state.timer = null; progress(""); }

  function clearResults() {
    state.run = null;
    state.source = null;
    state.previews = {};
    for (const id of ["tryit-detected", "tryit-recovered", "tryit-converted", "tryit-unresolved-count"]) $(id).textContent = "-";
    $("tryit-breakdown").textContent = "No analysis run yet.";
    $("tryit-source").hidden = true;
    fill($("tryit-unresolved"), h("div", { class: "placeholder", text: "Unresolved SQL sites of your project will be listed here." }));
    fill($("tryit-code"), h("div", { class: "placeholder", text: "models.py and data_access.py of your project will be previewed here." }));
    fill($("tryit-download"), h("div", { class: "placeholder", text: "A download of the generated data layer will be offered here after a run." }));
    fill($("tryit-impact"), h("div", { class: "placeholder", text: "The Migration Impact of your project (each SQL site next to its generated function, schema models and flagged sites) will be shown here after a run." }));
  }

  // Migration Impact of a live run, read from the bridge before any download (the download deletes the run).
  function renderImpactInto(source, summary) {
    const box = $("tryit-impact");
    if (source !== "live") {
      return fill(box, h("p", { class: "muted", text: "Migration Impact is built from a live run. For the recorded NEWS-BUZZ benchmark, see the Migration Impact section of the evidence tab." }));
    }
    fill(box, h("p", { class: "muted", text: "Loading Migration Impact…" }));
    return getJson(`${API}runs/${state.run}/before_after`)
      .then((payload) => MigrationImpact.render(box, payload, { label: summary.upload.zip_name, role: "live upload", live: true,
        countsOnlyText: "Detail is not available for this run." }))
      .catch((error) => fill(box, h("p", { class: "muted", text: error.message })));
  }

  function render(summary, unresolved, source, note) {
    const c = summary.counts;
    state.run = summary.run_id;
    state.source = source;
    $("tryit-count-label").textContent = summary.label;
    $("tryit-detected").textContent = String(c.sql_detected);
    $("tryit-recovered").textContent = String(c.sql_recovered);
    $("tryit-converted").textContent = String(c.converted_functions);
    $("tryit-unresolved-count").textContent = String(c.unresolved_sites);
    $("tryit-breakdown").textContent = `Converted by general rules: ${c.converted_by_general_rules}; by query-specific templates: `
      + `${c.converted_by_query_specific_template}. Unresolved at recovery: ${c.unresolved_recovery_stage}; at conversion: `
      + `${c.unresolved_conversion_stage}. Upload: ${summary.upload.zip_name} (${summary.upload.php_files} .php files used, `
      + `${summary.upload.files_skipped} other files ignored) with ${summary.upload.schema_name}; C3 ran for ${summary.duration_seconds} s.`;
    const badge = $("tryit-source");
    badge.textContent = source === "live" ? "Live run on this computer" : note;
    badge.className = `badge ${source === "live" ? "good" : "warn"}`;
    badge.hidden = false;

    const sites = unresolved.sites;
    fill($("tryit-unresolved"), sites.length ? h("div", { class: "table-wrap" }, h("table", {},
      h("thead", {}, h("tr", {}, ["Query ID", "PHP file:line", "Stage", "Reason"].map((x) => h("th", { text: x })))),
      h("tbody", {}, sites.map((s) => h("tr", {},
        h("td", { text: s.query_id }), h("td", {}, h("code", { text: `${s.file}:${s.line}` })), h("td", { text: s.stage }),
        h("td", { text: s.reason ? `${s.reason_code}: ${s.reason}` : (s.reason_code || "-") }))))))
      : h("p", { class: "muted", text: "C3 converted every detected SQL site of this upload; nothing was flagged for review." }));

    fill($("tryit-code"),
      h("div", { class: "code-tabs", role: "tablist" }, ["models.py", "data_access.py"].map((name) =>
        h("button", { type: "button", class: "sub-tab code-tab", role: "tab", "data-file": name, text: name,
          onclick: () => renderPreviewInto(name) }))),
      h("div", { id: "tryit-code-view" }));
    renderPreviewInto("models.py");
    renderImpactInto(source, summary);

    fill($("tryit-download"), source === "live"
      ? [h("a", { class: "button primary", href: `${API}runs/${state.run}/download`, download: "", text: "Download generated outputs (.zip)",
        onclick: () => setTimeout(() => fill($("tryit-download"), h("p", { class: "muted",
          text: "Downloaded. The temporary run folder is deleted after the download; run the analysis again to regenerate it." })), LAYOUT.msPerSecond) }),
        h("p", { class: "muted", text: "Contains models.py, data_access.py, unresolved_queries.json, the reports and the alembic folder." })]
      : h("p", { class: "muted", text: "Download is only available for live runs." }));
  }

  function renderPreviewInto(name) {
    const view = $("tryit-code-view");
    for (const tab of document.querySelectorAll(".code-tab")) tab.setAttribute("aria-selected", String(tab.dataset.file === name));
    const show = (p) => fill(view,
      p.truncated ? h("p", { class: "muted", text: `Preview truncated: showing the first part of ${p.file}. Download the outputs for the full file.` }) : null,
      h("pre", { class: "code-preview" }, h("code", { text: p.text })));
    if (state.previews[name]) return show(state.previews[name]);
    if (state.source !== "live") return fill(view, h("p", { class: "muted", text: "No preview recorded for this file." }));
    fill(view, h("p", { class: "muted", text: `Loading ${name}…` }));
    return getJson(`${API}runs/${state.run}/file/${name}`)
      .then((p) => { state.previews[name] = p; show(p); })
      .catch((error) => fill(view, h("p", { class: "muted", text: error.message })));
  }

  async function analyze() {
    const zip = chosen("php-zip");
    const sql = chosen("schema-sql");
    if (!zip) return showError("Choose the PHP project ZIP first.");
    if (!sql) return showError("Choose the MySQL schema (.sql) file first.");
    showError("");
    clearResults();
    state.busy = true;
    updateButton();
    startTimer();
    const form = new FormData();
    form.append("php_zip", zip, zip.name);
    form.append("schema_sql", sql, sql.name);
    try {
      const summary = await getJson(`${API}analyze`, { method: "POST", body: form });
      const unresolved = await getJson(`${API}runs/${summary.run_id}/unresolved`);
      render(summary, unresolved, "live");
    } catch (error) {
      showFailure(error);
    } finally {
      stopTimer();
      state.busy = false;
      updateButton();
    }
  }

  async function loadSample() {
    showError("");
    clearResults();
    try {
      const sample = await getJson(SAMPLE);
      state.previews = sample.previews || {};
      render(sample.summary, sample.unresolved, "recorded", `${sample.label} · recorded ${sample.recorded_at}`);
    } catch (error) {
      showError(`No recorded sample run is available (${error.message}).`);
    }
  }

  async function connect() {
    try {
      const info = await getJson(`${API}limits`);
      const l = info.limits;
      state.connected = true;
      $("tryit-status").className = "notice info";
      $("tryit-status").textContent = "Connected to the local C3 bridge on this computer. Uploads go only to this computer and are "
        + "processed in a temporary folder outside the repository, which is deleted after the download or after an hour.";
      $("tryit-limits").textContent = `Limits: ZIP up to ${megabytes(l.zip_bytes)} MB and ${l.zip_files} files `
        + `(${megabytes(l.extracted_bytes)} MB extracted); schema up to ${megabytes(l.sql_bytes)} MB; `
        + `${l.timeout_seconds / LAYOUT.secondsPerMinute} minute timeout; one run at a time. Only .php files are used.`;
    } catch (error) {
      state.connected = false;
      $("tryit-status").className = "notice";
      $("tryit-status").textContent = "Local migration connection not available. Start the local server with "
        + "components/c3_data_layer/dashboard/server.py to analyse your own project.";
    }
    updateButton();
  }

  function init() {
    const zip = $("php-zip");
    const sql = $("schema-sql");
    zip.addEventListener("change", () => describe(zip, $("php-zip-name")));
    sql.addEventListener("change", () => describe(sql, $("schema-sql-name")));
    $("run-migration").addEventListener("click", analyze);
    $("load-sample").addEventListener("click", loadSample);
    clearResults();
    updateButton();
    connect();
  }
  return { init };
})();
/* ===== END TRY IT ===== */

/* ===== SHELL: tabs, routing, theme ===== */
(() => {
  const THEME_KEY = "c3-studio-theme";

  function applyTheme(theme) {
    document.documentElement.setAttribute("data-theme", theme);
    const toggle = document.getElementById("theme-toggle");
    toggle.textContent = theme === "dark" ? "Light theme" : "Dark theme";
    toggle.setAttribute("aria-pressed", String(theme === "dark"));
  }

  function route() {
    const [tab, section] = (location.hash.replace(/^#\/?/, "") || "evidence/functions").split("/");
    const active = tab === "tryit" ? "tryit" : "evidence";
    for (const button of document.querySelectorAll(".main-tab")) {
      button.setAttribute("aria-selected", String(button.dataset.tab === active));
    }
    document.getElementById("panel-evidence").hidden = active !== "evidence";
    document.getElementById("panel-tryit").hidden = active !== "tryit";
    Evidence.closeDrawer();
    if (active === "evidence") Evidence.setSection(section || "functions");
  }

  let theme = "light";
  try { theme = localStorage.getItem(THEME_KEY) === "dark" ? "dark" : "light"; } catch (error) { theme = "light"; }
  applyTheme(theme);
  document.getElementById("theme-toggle").addEventListener("click", () => {
    theme = theme === "dark" ? "light" : "dark";
    applyTheme(theme);
    try { localStorage.setItem(THEME_KEY, theme); } catch (error) { /* storage unavailable: theme still applies */ }
  });
  for (const button of document.querySelectorAll(".main-tab")) {
    button.addEventListener("click", () => { location.hash = button.dataset.tab === "tryit" ? "#/tryit" : "#/evidence/functions"; });
  }
  for (const button of document.querySelectorAll(".sub-tab")) {
    button.addEventListener("click", () => { location.hash = `#/evidence/${button.dataset.section}`; });
  }
  window.addEventListener("hashchange", route);
  TryIt.init();
  Evidence.init().then(route);
})();
